programs.sol:
"""A partial detector of scientific functions and physical extent.

Named signals and mathematical representations give a small positive value.
Time/space/axis modifiers strengthen it; functional dependence and complex
number parts are especially positive. Surface area and other extent phrases
are negative. A following 'of' carries the noun-family response. The short
text state also recognizes split compounds, double middle dots, and an initial
Title: label. Unrecognized tokens are zero; documents reset the state.
"""
import re

READS = ()
REPRESENTATIONS = set('''signal stream curve spectrum spectra spectral coordinate
vector function derivative data value distribution sequence variation direction
profile resolution plot graph space plane'''.split())
EXTENT = set('''area volume size length mass weight perimeter distance radius
slope resistance temperature velocity dimension displacement'''.split())
QUALIFIERS = set('''time spatial spatially x y z t radial angular vertical
horizontal transverse longitudinal axial polar cartesian frequency momentum
energy velocity temperature pressure field spectral phase spin wave scalar
complex real imaginary density voltage acceleration'''.split())
DESCRIPTIONS = REPRESENTATIONS | set('''component part evolution series domain
variable dependence dependent averaged average varying discret discretization
interval stamp diagram point step'''.split())
MATH_MODIFIERS = set('''cost target weight distance likelihood error density
continuous differentiable quadratic linear homogeneous fractional integer
odd exponent principal'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, previous, response = '', '', 0.0
    if carry is not None and carry[0] == doc:
        _, tail, previous, response = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('-')
    if word.endswith('s') and word[:-1] in DESCRIPTIONS | EXTENT:
        word = word[:-1]
    m = re.search(r'([A-Za-z]+)[\s\-‐‑]*\Z', tail)
    modifier = m[1].lower() if m else ''
    value = 0.0
    boundary = (not tail or token[:1].isspace() or token.startswith('-')
                or tail[-1:].isspace() or tail[-1:] in {'-', '‐', '‑'})
    if boundary:
        if word in REPRESENTATIONS:
            value = 0.35
        elif word in EXTENT:
            value = -0.1
        elif word == 'part':
            value = -0.2
        elif word == 'component':
            value = 0.2
        if word == 'dependence':
            value = 3.0 if modifier == 'the' else 2.1
            if modifier in {'our', 'their', 'your', 'drug'}:
                value = 0.0
        if word in DESCRIPTIONS and modifier in QUALIFIERS:
            value = 2.0
        if modifier == 'time' and word in {
            'dependent', 'dependence', 'component', 'evolution'
        }:
            value = 4.4
        if word == 'dependence' and modifier in QUALIFIERS:
            value = 5.0
        if word in {'part', 'component', 'function', 'derivative'}:
            if modifier in MATH_MODIFIERS:
                value = 1.5
        if word == 'part' and modifier in {'real', 'imaginary', 'spatial'}:
            value = 3.3
        if word == 'area' and modifier == 'surface':
            value = -3.3
        if word == 'size' and modifier == 'sample':
            value = -2.4
        if word in {'weight', 'mass'} and modifier in {'molecular', 'molar'}:
            value = -1.5
        if word == 'to' and previous in {'relative', 'referred'}:
            value = -0.8
        if word == 'to' and previous == 'proportional':
            value = 1.2
        if word == 'of':
            if previous in EXTENT:
                value = -0.65
                if previous == 'area':
                    value = -2.3 if response < -1 else -1.2
            elif previous == 'dependence':
                value = 3.8 if response > 1.5 else 0.0
            elif previous in {'part', 'component'}:
                value = min(3.3, 0.8 * response + 0.5) if response > 0 else 0.0
            elif previous in REPRESENTATIONS:
                value = 0.5

    joined = (tail + token).lower()
    m = re.search(r'\btime[-‐‑ ](v|vary|varying)\Z', joined)
    if m:
        value = {'v': 2.7, 'vary': 1.6, 'varying': 4.0}[m[1]]
    if re.search(r'\btime[-‐‑ ]ev(?:olved|olution)?\Z', joined):
        value = 3.8
    if re.search(r'\b(?:real|complex)[-‐‑ ]val(?:ued)?\Z', joined):
        value = 2.7
    if joined.endswith('timeseries'):
        value = 3.0
    if token == '··':
        value = 2.14
    if token == ':' and tail == 'Title':
        value = 4.95
    return (doc, (tail + token)[-100:], word, value), float(value)

"""Reference-format detector, chiefly scientific citations and cross-references.

Recognize bibliography-key prefixes after [@; numbered link anchors, figure
and section labels; ref-type attributes; and journal volume(issue): notation.
Also match lettered parentheses after numbers. Other text gets zero. Fitted
strengths distinguish familiar abbreviations and parenthesized citation
keys, not individual token IDs. State resets at document boundaries.
"""
import re

READS = ()

# Bibliography, reference, and cross-reference key prefixes.
CITATION_PREFIX = {'b': 9.0, 'r': 10.5, 'bib': 16.0,
                   'ref': 13.0, 'cr': 14.8}


def response(before, token):
    lower = token.lower()
    if token == '#' and before.endswith(']('):
        if re.search(r'\[[^\]\n]*\d[^\]\n]*\]\($', before):
            return 5.0 if re.search(r'\[\d+\]\($', before) else 4.0
        return 0.0
    if token == '#' and before.endswith('{'):
        return 5.1 if before.endswith('){') else 2.6
    if token.strip() == '[@':
        return 1.3
    if token == '@' and before.endswith('['):
        return 2.2

    if before.endswith('@') and re.search(r'\[@[^\]\n]*$', before):
        if token == 'B' and before.endswith('([@'):
            return 11.7
        if lower in CITATION_PREFIX:
            return CITATION_PREFIX[lower]
        if token.isdigit():
            return 3.1
        if token.isalpha():
            return 4.5 if token.isupper() and len(token) <= 2 else 1.0
    # Some token boundaries split the abbreviations CIT and BIB.
    if re.search(r'\[@CIT$', before + token):
        return 7.0
    if re.search(r'\[@BIB$', before + token):
        return 5.5

    numbered_link = before.endswith('](#') and re.search(
        r'\[[^\]\n]*\d[^\]\n]*\]\(#$', before)
    if token.isalpha() and (before.endswith('{#') or numbered_link):
        if lower in ('sec', 'section'):
            return 8.5 if lower == 'sec' else 5.5
        if lower in ('fig', 'figure', 'f'):
            return 5.0 if lower == 'f' else 7.0
        if lower in ('tab', 'table', 'tbl', 't'):
            return 3.5
        if lower in ('s', 'sup'):
            return 5.5
        if token.isupper():
            return 4.0
        return 2.5 if len(token) <= 2 else 1.3
    if token == 'ref' and before.endswith('){'):
        return 4.0
    if token == '-type' and before.endswith('){ref'):
        return 5.4
    if token == 'ref' and before.endswith('ref-type="'):
        return 1.85
    if token == 'ib' and before.endswith('-b'):
        return 5.1
    if token == '.ref' and re.search(r'\[@[^\s\]]+$', before):
        return 4.2
    if token.isdigit() and before.endswith('.ref'):
        return 1.5

    if token == '):' and re.search(
            r'\b\d{1,3}\s*\(\d{1,2}(?:[–-]\d+)?$', before):
        return 6.0
    if token == '(' and re.search(
            r'(?:[A-Za-z.]\s+|[;,]\s*)\d{1,3}$', before):
        if re.search(r'\b(?:19|20)\d{2};\s*\d{1,3}$', before):
            return 6.5
        return 3.0
    if re.fullmatch(r'\([a-f]', token) and before[-1:].isdigit():
        return 0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(before, token)
    return (doc, (before + token)[-100:]), value

"""A document-initial formatting pulse.

The signal is large on an opening blank line, tab, quotation or code prologue,
then nearly disappears once content follows. Repeated copies of the opening
token keep the pulse alive. Values are approximate training averages; ordinary
words and their token-specific differences are deliberately not memorized.
"""
import unicodedata

READS = ()


def opening_value(s):
    if s == '<|endoftext|>':
        return 18.14
    if s.startswith('<|'):
        return 0.0
    # Invisible initial separators have particularly large pulses.
    if s == '\u200b':
        return 11.4
    if s == '\x00':
        return 8.08
    if s.isspace():
        if s == '\t':
            return 9.26
        if s == '\r':
            return 4.8
        if s == '\r\n':
            return 7.88
        if s.strip('\n') == '':
            return 3.9 if len(s) == 1 else 7.35
        if '\xa0' in s:
            return 6.52 if len(s) == 1 else 3.5
        if '\n' in s:
            return 5.7 if '\t' in s else 3.1
        if s.strip('\t') == '':
            return 2.5
        return 0.34 if len(s) == 1 else -0.25
    if '\n' in s:
        core = s.strip()
        if core in ('"""', "'''"):
            return 14.0
        if core in ('/*', '//'):
            return 10.0
        if core == '/**':
            return 7.4
        if core.startswith('/*'):
            return 2.5
        if core in ('.', '。'):
            return 3.2 if s.count('\n') == 1 else 3.9
        return 2.25
    if s.startswith('#include'):
        return 3.22
    if s.startswith('#!'):
        return 3.87
    if s in ('package', 'import'):
        return -1.3
    if s == '[':
        return 6.53
    if s == '<':
        return 4.08
    if s in '《【“‘„' and len(s) == 1:
        return 5.7
    if s == ' .':
        return 5.54
    if s == '"':
        return 2.95
    if s == ' “':
        return 3.4
    if s and not s.strip('·'):
        return 3.77
    if s == '․':
        return 3.19
    if s == '**':
        return 9.65
    if s == '*':
        return 2.66
    if s in (',', ':', '-'):
        return -0.3
    if s.startswith('#'):
        return -0.4
    if s and all(unicodedata.category(c).startswith('P') for c in s):
        return 0.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(prefix.token_strings[-1])
        return (doc, token, True, value), value
    _, first, initial_run, value = carry
    initial_run = initial_run and token == first
    return (doc, first, initial_run, value), value if initial_run else 0.003

"""Numerical fragments, with supplementary number-word and brevity responses.

Leading 19/20 are date-like: calendar words and parentheses raise their
response. Inside longer numbers they instead get a small negative value.
Other numerical rules cover 30/31, 65, and five (stronger after letters,
negative after a dot). Number-word completions and short/shortly/kurz/kort
add separate pulses; Chinese 一九 gets a year-prefix pulse too. Unmatched
tokens use small baselines. State resets at document boundaries.
"""
import re
import regex
import inflect

READS = ()
_inflect = inflect.engine()
NUMBER_WORDS = {_inflect.number_to_words(n) for n in (5, 15, 30)}
NUMBER_WORDS |= {_inflect.ordinal(w) for w in tuple(NUMBER_WORDS)}
NUMBER_WORDS.add(_inflect.plural(_inflect.number_to_words(5)))
MONTHS = set('january february march april may june july august september '
             'october november december'.split())
DATE_CUES = MONTHS | set('in since born died copyright year years during '
                         'until from circa published released founded '
                         'established'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        tail, digits, previous = '', '', ''
    else:
        _, tail, digits, previous = carry
    token = prefix.token_strings[-1]
    joined = tail + token
    value = -0.004

    if token.isascii() and token.isdigit() and len(token) == 1:
        value = -0.013
        pair = digits[-1:] + token
        if digits and pair in ('19', '20'):
            if len(digits) > 1:
                value = -0.08 if pair == '19' else -0.19
            else:
                before = tail[:-1]
                words = re.findall('[a-z]+', before.lower())
                if words and words[-1] in DATE_CUES:
                    value = 0.73 if pair == '19' else 0.57
                elif '(' in before[-20:]:
                    value = 0.55 if pair == '19' else 0.42
                elif regex.search(r'\p{Script=Han}', before[-5:]):
                    value = 0.55
                elif not before or before[-1:].isspace():
                    value = 0.44 if pair == '19' else 0.28
                else:
                    value = 0.13
        elif digits and pair in ('30', '31', '65'):
            value = {'30': 0.49, '31': 0.28, '65': 0.44}[pair]
            if len(digits) > 1:
                value = {'30': 0.20, '31': 0.065, '65': 0.36}[pair]
        elif token == '5':
            if previous.endswith('.'):
                value = -0.19
            elif tail[-1:].isalpha():
                value = 0.49
            elif not digits:
                value = 0.13
            else:
                value = 0.01
    else:
        match = re.search(r'(?:^|\W)([A-Za-z]+)$', joined)
        word = match.group(1).lower() if match else ''
        if word in NUMBER_WORDS:
            value = 0.22 if word in ('five', 'fives') else 0.34
            if len(word) > len(token.strip()):
                value = 1.2
        elif word == 'short':
            value = 0.15
        elif word == 'shortly':
            value = 0.65
        elif word in ('kurz', 'kort'):
            value = 1.2 if word == 'kurz' else 0.85
        elif joined.endswith('一九'):
            value = 1.2
        elif first:
            value = -0.11

    if token.isascii() and token.isdigit():
        digits = (digits + token)[-16:]
    else:
        digits = ''
    return (doc, joined[-100:], digits, token), value

