"""Year-digit and name-digit detector (layers.1.mlp.down_proj:2051)."""

READS = ()

START = {"19": 0.4, "20": 0.25, "30": 0.42, "31": 0.2, "65": 0.4}
DATE_CUES = {"January", "February", "March", "April", "June", "July", "August", "September",
             "October", "November", "December", "born", "al", "In", "in", "Date", "©", "年",
             "。", "(", "Copyright", "on", "since", "from", "to", "and"}
CODE_CUES = {"=", "$", "[", "^", "...", "  ", "   ", "\n", "{", "}", ";", "×", "+", "*", "/", "_"}


def is_digit(s):
    return len(s) == 1 and s.isdigit()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = len(toks) - 1
    if t < 1 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, 0.0
    cur, prev = toks[t], toks[t - 1]
    before = toks[t - 2] if t >= 2 else ""
    value = 0.0
    if is_digit(cur) and is_digit(prev) and not is_digit(before):
        value = START.get(prev + cur, 0.0)
        if value:
            recent = [s.strip() or s for s in toks[max(0, t - 8):t - 1]]
            value += 0.2 * sum(s in DATE_CUES for s in recent) - 0.06 * sum(s in CODE_CUES for s in recent)
    elif cur == "5" and prev.strip().isalpha():
        value = 0.46
    elif cur == "5" and prev == " ":
        value = 0.16
    return None, value

programs.sol:
"""A local spelling approximation for an o--g detector.

Short written 'og' sequences contribute negatively. The strongest rule is
'o' followed by a new token starting with 'g'. A weaker signal survives into
an unspaced continuation. Latin, Greek and Cyrillic letters share these
rules after table-based transliteration; other scripts are not romanized.
The small letter-environment corrections below are fitted on training text.
Repeated middle dots are a separate positive feature. No meaning or distant
context is inferred, and document boundaries clear the previous spelling.
"""
from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()


@lru_cache(maxsize=65536)
def spelling(text):
    alphabet = r'[\p{Latin}\p{Greek}\p{Cyrillic}\p{Common}\p{Inherited}]*'
    if regex.fullmatch(alphabet, text):
        return anyascii(text).lower()
    return text.lower()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    raw = prefix.token_strings[-1]
    token = spelling(raw)
    word = token.strip()
    value = 0.00015

    # Embedded og, with different gains for familiar letter environments.
    if 'og' in word and len(word) <= 6:
        value -= 0.64
        if word.endswith('og'):
            value += 0.08
        if word.startswith('og'):
            value -= 0.65
            if token.startswith(' '):
                value += 1.13
        if len(word) == 2:
            value -= 0.67
        if len(word) == 6:
            value += 0.17
        if word.startswith(('log', 'olog')):
            value += 0.41
        if 'rog' in word:
            value -= 0.95
        if 'fog' in word or 'vog' in word:
            value -= 1.20
        if any(part in word for part in ('ogen', 'ogram', 'ograph')):
            value += 0.65
        # Cyrillic og followed by a vowel is often a fused inflection.
        if regex.search(r'ог[аоеиу]', raw.lower()):
            value += 0.71

    if word.endswith('eg') and len(word) <= 5:
        value += 0.03

    # Effects across a token boundary, not across a space or punctuation.
    if token and token[0].isalpha() and len(token) <= 4:
        if token.startswith('g'):
            last = previous[-1:]
            value += {'o': -2.84, 'u': -0.93, 'e': 0.05,
                      'd': 0.11, 't': 0.16, 'r': -0.03}.get(last, 0)
            if last == 'o':
                if len(token) == 1:
                    value -= 1.54
                if len(token) >= 3:
                    value += 0.97
                if token.startswith('gl'):
                    value -= 1.69
        if previous.endswith('og'):
            value -= 0.69
            if token.startswith('g'):
                value -= 1.03
        elif previous.endswith(('ug', 'rg')):
            value -= 0.06

    if len(raw) >= 2 and all(char == '·' for char in raw):
        value += 0.72
    return (document, token), float(value)

"""A spelling-family approximation, not a topic detector.

CH/CL followed by a/ai/ay/al spellings often gives positive responses;
chile/chili/chill and many short i-continuations give negative ones.
Split fragments differ from fused word tokens, so both are handled.
Small dictionary-based Chinese equivalents and document-start biases are
included. Remaining contextual variation is not reconstructed.
"""
import re
import unicodedata
from functools import lru_cache
import cedict

READS = ()

# Short syllabic fragments immediately following a token ending in CH.
CH_FRAGMENTS = {
    'al': 0.9, 'ai': 1.7, 'ar': 0.9, 'ao': 1.3, 'ay': 4.0,
    'il': -3.6, 'ia': 0.9, 'ir': -1.6, 'is': -1.2,
    'it': -0.7, 'ih': -1.8, 'im': -0.3,
    'or': 0.3, 'ok': 1.7, 'ol': 0.4,
}
SPELLINGS = {
    'charcoal': 9.7, 'biochar': 8.8, 'charles': 2.2,
    'charlie': 1.0, 'cheryl': 1.3, 'clarke': 1.4,
    'clay': 3.8, 'chalk': 8.1, 'coal': 0.8, 'coral': 1.2,
    'chili': -5.5, 'chile': -0.1, 'chill': -5.1,
    'clash': -1.8, 'chopped': -0.8,
}
ROOTS = re.compile('|'.join(SPELLINGS))


@lru_cache(maxsize=4096)
def chinese_response(token):
    if len(token) not in (1, 2) or token.isascii():
        return None
    gloss = '; '.join(cedict.glosses(token)).lower()
    for word, value in (
        ('charcoal', 5.9), ('carbon', 1.0),
        ('chili', -2.7), ('chilli', -2.7), ('cold', -0.6),
    ):
        if re.search(r'\b' + word + r'\b', gloss):
            return value
    return None


def response(old, token, first):
    s, p = token.lower(), old.lower()
    continuation = bool(s) and s[0].isalpha()
    if old == '1' and token == '2':
        return -2.73  # The numeral 12 at the beginning of a document.
    if continuation and p.endswith('ch'):
        for endings, value in (
            (('alk', 'alc'), 8.4),
            (('ile', 'ilies', 'ills', 'illed'), -6.8),
            (('att',), -2.7), (('ock',), 4.4),
            (('ais',), 2.6), (('oi', 'oy'), 2.8), (('au',), 0.5),
        ):
            if s.startswith(endings):
                return value
        if s in ('l', 'ł', 'sl'):
            return -1.2
        if len(s) <= 3 and s[:2] in CH_FRAGMENTS:
            return CH_FRAGMENTS[s[:2]]
    if continuation and p.endswith(('clo', 'cho')) and s.startswith('al'):
        return 6.0
    if continuation and p.endswith('cl'):
        for ending, value in (
            ('ay', 5.2), ('iff', 2.1), ('air', 1.3), ('an', -0.9),
        ):
            if s.startswith(ending):
                return value
        if s in ('one', 'ones'):
            return -2.1
    if continuation and p.endswith('ч'):
        if s in ('ит', 'ис', 'ил', 'их'):
            return -1.3
        if s in ('ар', 'ал', 'ай', 'аль'):
            return 1.5
        if s.startswith('л'):
            return -2.1
        if s == 'ех':
            return -3.3

    joined = p + s
    for m in ROOTS.finditer(joined):
        if m.end() <= len(p):
            continue
        root = m.group()
        if root == 'chill' and m.start() and joined[m.start()-1].isalpha():
            continue  # Not the same response in, for example, Churchill.
        if root == 'chalk' and m.start() >= len(p):
            return 8.1 if token[:1].isspace() else 3.2
        if root in ('chile', 'chili') and token.lstrip()[:1].isupper():
            return -2.2 if root == 'chile' else -4.9
        return SPELLINGS[root]

    # Inflected continuations of the same spelling families.
    if continuation:
        if re.search(r'(?:^|[^a-z])chill$', p):
            return -6.0
        if p.endswith('char') and s.startswith(('r', 'l')):
            return 4.0
        if p.endswith('chalk') and s in ('ed', 'y', 'ing'):
            return 4.5
    translated = chinese_response(token.strip())
    if translated is not None:
        return translated
    if s == '··' and p.endswith('··'):
        return -1.6
    if first:
        stripped = token.strip()
        if not stripped:
            return -0.1
        if stripped.startswith('#'):
            return 0.65
        if stripped.isascii():
            return -0.2 if stripped.isalpha() else 0.0
        name = unicodedata.name(stripped[0], '')
        if 'CJK' in name or 'IDEOGRAPH' in name:
            return 0.0
        return -0.47 if 'CYRILLIC' in name else -0.22
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    old = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = response(old, token, first)
    return (doc, (old + token)[-16:]), value

"""Local indefinite-quantity and counting constructions.

Positive values mark extent ('a large', 'a long'), vague amounts ('a lot'),
and several common indefinite-noun phrases.  Negative values mark counting
another item, ordinals, contrast, and whole/full or uncertain descriptions.
The preposition closing a short phrase can keep its sign.  This is a small
lexical approximation, not a general grammatical or semantic analysis.
"""
READS = ()

import inflect

_numbers = inflect.engine()
CARDINAL = {_numbers.number_to_words(i) for i in range(1, 21)}
ORDINAL = {_numbers.number_to_words(_numbers.ordinal(i))
           for i in range(1, 11)} | {'last', 'final'}
AMOUNTS = {'lot', 'amount', 'number', 'variety', 'range', 'portion',
           'majority', 'plurality', 'average', 'ton'}
OF_NOUNS = AMOUNTS | {'part', 'result', 'account', 'deal', 'list', 'piece', 'set',
                     'sense', 'mix', 'kind', 'sort', 'group', 'copy', 'version'}
TO_NOUNS = {'opportunity', 'chance', 'ability', 'responsibility', 'request',
            'response', 'answer', 'need', 'motive', 'effort'}
IN_NOUNS = {'increase', 'rise', 'interest', 'change', 'reduction', 'decrease'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = history[-1] if history else ''
    article = prev in {'a', 'an'}
    recent_article = bool({'a', 'an'} & set(history[-3:]))
    numeral = prev.isdigit()
    counted = prev in CARDINAL or numeral
    value = 0.0
    if word in {'more', 'less', 'extra', 'additional', 'further'}:
        value = -0.3
    if word in {'thing', 'things'}:
        value = 0.5
    if word == 'another':
        value = -0.7

    if raw[:1].isspace():
        if article:
            if word in {'extra', 'further'}:
                value = -6.7
            elif word == 'additional':
                value = -5.4
            elif word == 'lot':
                value = 2.9
            elif word == 'long':
                value = 3.0
            elif word == 'large':
                value = 2.3
            elif word == 'wide':
                value = 1.7
            elif word in {'big', 'short', 'small'}:
                value = 1.0
            elif word in {'high', 'low', 'good', 'great', 'certain', 'better',
                          'larger', 'higher', 'greater', 'strong', 'significant'}:
                value = 0.6
            elif word in {'result', 'account', 'majority', 'impact', 'thing'}:
                value = 2.7
            elif word in {'part', 'person', 'place', 'deal', 'emphasis', 'chance',
                          'opportunity'}:
                value = 1.8
            elif word in AMOUNTS | {'while', 'purpose', 'opportunity', 'idea'}:
                value = 0.9
            elif word in {'second', 'third', 'possible'}:
                value = -2.4
            elif word == 'entire':
                value = -3.2
            elif word in {'separate', 'different', 'fresh', 'mere'}:
                value = -2.1
            elif word in ORDINAL | {'full', 'whole', 'initial'}:
                value = -1.6
            elif word in {'time', 'matter', 'factor'}:
                value = -1.8
            elif word in {'more', 'other', 'further', 'less', 'estimated', 'alleged'}:
                value = -1.3
            elif word in {'interesting', 'strange'}:
                value = -1.0
            elif word in {'new', 'similar'}:
                value = -0.3

        if counted:
            if word in {'more', 'last'}:
                value = -4.5 if not numeral else -2.3
            elif word in {'other', 'in', 'time', 'times'}:
                value = -1.5 if not numeral else -0.7
            elif word in {'extra', 'additional', 'further'}:
                value = -2.7
            elif word == 'of':
                value = -0.8 if numeral else (0.0 if prev == 'one' else -0.4)
            elif word == 'at' and prev == 'one':
                value = -0.9
        if word == 'more':
            if prev in {'or', 'few'}:
                value = -2.0
            elif prev == 'couple':
                value = -5.0
            elif prev in {'once', 'bit', 'slightly', 'add', 'adding'}:
                value = -1.5
        if word == 'final' and prev == 'one':
            value = -2.5
        if word == 'other' and prev == 'every':
            value = -1.6
        if word == 'time' and prev in ORDINAL | {'more'}:
            value = -1.4
        if recent_article:
            if word == 'of':
                if prev in OF_NOUNS:
                    value = 0.6
                    if prev in {'part', 'result', 'account', 'portion', 'deal'}:
                        value = 2.0
                elif prev in {'factor', 'matter'}:
                    value = -2.4
            elif word == 'to' and prev in TO_NOUNS:
                value = 1.2
            elif word == 'in' and prev in IN_NOUNS:
                value = 1.0
            if word in {'idea', 'place', 'deal', 'time', 'thing'} and prev in {
                'good', 'great', 'hard'}:
                value = 2.2
            if word in AMOUNTS and prev in {'large', 'small', 'massive', 'considerable'}:
                value = 1.7
            if word in {'impact', 'effect', 'role'} and prev in {
                'major', 'great', 'big', 'important', 'significant', 'positive',
                'negative', 'key', 'vital', 'crucial'}:
                value = 2.4
            if word == 'time' and prev == 'long':
                value = 2.7
            if word == 'deal' and prev == 'great':
                value = 3.8
            if word == 'part' and prev == 'integral':
                value = 2.0
    if word == '/' and prev == '1':
        value = -0.7
    if word == '-time' and counted:
        value = -2.2
    return (doc, (*history[-3:], word)), value

programs.haiku:
"""Layer 1, MLP down-projection component 2055.

What it does: a word-meaning feature on the word right after an article ("a", "an",
"one"). The sign follows the word's meaning:

* Positive for words of size, amount or extent that begin a quantity phrase:
  "a lot of", "a large number of", "a wide variety of", "a long time",
  "a significant increase", "a majority of", "a result of".
* Strongly negative for words of addition and sequence: "a further", "an extra",
  "an additional" (the largest responses), more mildly negative for "a second",
  "a different", "a separate", "a whole", "a full".
* "more" after a number ("one more", "a few more") is negative.
* Small values for the same words elsewhere, and small signs after "part of" and
  "factor of". Everything else predicts 0.
"""

READS = ()

ARTICLES = {" a", " an", " A", " An", " one", " One"}

# size, amount and extent words
MAGNITUDE = {
    " lot", " result", " impact", " thing", " things", " majority", " account", " long",
    " large", " part", " reason", " demand", " place", " wide", " chance", " lack",
    " opportunity", " person", " diverse", " variety", " short", " serious", " big",
    " substantial", " considerable", " huge", " great", " high", " higher", " larger",
    " strong", " significant", " increase", " decrease", " risk", " threat", " loss",
    " amount", " role", " number", " deal", " basis", " idea", " effect", " broad",
    " detailed", " comprehensive", " problem", " need", " percentage", " average",
}

# addition and sequence words that give the strongest negative responses
STRONG_NEGATIVE = {" further", " extra", " additional"}

# other distinctness and order words
DISTINCT = {
    " another", " other", " more", " less", " second", " third", " fourth", " first",
    " final", " initial", " subsequent", " previous", " recent", " possible", " different",
    " separate", " similar", " fresh", " full", " whole", " entire", " mere", " alternative",
    " time", " matter", " factor", " level", " degree", " side", " light", " former", " key",
    " particularly",
}

NUMBER_WORDS = {" one", " two", " three", " four", " five", " few", " couple", " or", " several"}
OF_POSITIVE = {" part", " lot", " summary", " overview", " account", " deal", " proportion",
               " portion", " plurality", " list", " group", " majority", " variety"}
OF_NEGATIVE = {" factor", " matter", " layer", " level", " aspect"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = None
    else:
        prev = prefix.token_strings[-2]
    after_article = prev in ARTICLES
    if cur == " more" and prev in NUMBER_WORDS:
        return None, -4.0
    if cur == " of" and prev in OF_POSITIVE:
        return None, 0.6
    if cur == " of" and prev in OF_NEGATIVE:
        return None, -0.6
    if after_article:
        if cur in STRONG_NEGATIVE:
            return None, -6.0
        if cur in DISTINCT:
            return None, -2.0
        if cur in MAGNITUDE:
            return None, 2.0
        return None, 0.0
    if cur in STRONG_NEGATIVE:
        return None, -0.5
    if cur in MAGNITUDE:
        return None, 0.1
    if cur in DISTINCT:
        return None, -0.1
    return None, 0.0

"""Role "as": the word "as" (and Chinese 为 / 為, "as / to be") when it says what a thing
is used, chosen or designated as.

The component fires on "as" that follows a verb of use or choice and its object:
"use PHP as a CGI", "we chose PKA and AurB as counter screens", "used them as the basis",
and Chinese 以X为Y ("take X as Y"). It is weaker after serve / act / work / treat verbs,
and zero for fixed degree phrases ("such as", "as well", "as long as", "same as").
The determiner right after such an "as" ("as the", "as a") carries a larger version of
the same signal. Other "as" (clause "as", "as he ...") gets a small positive value; the
small negatives the data shows for clause "as" are not modelled.
"""

from collections.abc import Mapping

READS = ()

USE_VERBS = {"use", "uses", "used", "using", "chose", "choose", "chosen", "choosing",
             "employ", "employed", "utilize", "utilized", "adopt", "adopted", "select",
             "selected", "pick", "picked", "took", "take", "taken", "taking"}
SERVE_VERBS = {"serve", "serves", "served", "serving", "act", "acts", "acted", "work",
               "worked", "working", "function", "functions", "functioned", "treat",
               "treated", "regard", "regarded", "seen", "known", "defined", "described"}
DEGREE_WORDS = {"such", "well", "so", "much", "same", "long", "far", "soon", "as", "not",
                "even", "early", "possible", "just", "many", "few", "little"}
AS_WORDS = {" as", " As", " AS"}
DETERMINERS = {" a", " an", " the", " my", " your", " his", " her", " its", " their", " our"}
WINDOW = 5  # tokens to look back for a verb of use


def as_score(prefix, j):
    """How strongly the 'as' at position j is a role/use 'as'."""
    toks = prefix.token_strings
    prev = toks[j - 1].strip().lower() if j > 0 else ""
    if prev in DEGREE_WORDS:
        return 0.0
    recent = {t.strip().lower() for t in toks[max(0, j - WINDOW):j]}
    if recent & USE_VERBS:
        return 3.0
    if recent & SERVE_VERBS:
        return 1.0
    return 0.5


def step(carry, prefix, upstream: Mapping):
    j = prefix.position
    toks = prefix.token_strings
    tok = toks[j]
    if tok in AS_WORDS:
        return None, as_score(prefix, j)
    if tok[:1] in ("为", "為"):  # Chinese 为: "as / to be", strongest in 以X为Y
        return None, 5.5 if "以" in "".join(toks[max(0, j - 12):j]) else 0.8
    if j > 0 and toks[j - 1] in AS_WORDS and tok in DETERMINERS:
        return None, 1.4 * as_score(prefix, j - 1)
    return None, 0.0

programs.sol:
"""Coarse syntax-prefix detector.

Ordinary text is near zero. Give positive levels to opening multiline
structures, escapes, shell options/paths, printf codes and underscores.
Distinguish unary signs from subtraction. TeX line breaks and document-initial
code/title fields get negative levels. These rules capture large responses,
not the component's finer lexical and contextual variation.
"""
READS = ()
COMMANDS = set(
    'grep egrep fgrep head tail cat sed awk find xargs curl wget cp mv rm ls '
    'chmod cd git python python3 node pip bash sh zip tar test run install '
    'status checkout restore diff build log'.split()
)
DECLARATIONS = set(
    'from import using def class function func namespace package public private '
    'static extern struct enum typedef const var let void int string'.split()
)
TEX = tuple('\\' + word for word in
            'begin end frac left right text sqrt hfill lim color vec quad'.split())
FORMATS = frozenset('diuoxXfFeEgGaAcspnvqwtTbB')


def predict(s, previous, position, math):
    q, p = s.strip(), previous.strip()
    spaced = s.startswith(' ')
    if position == 1 and p == 'Title' and q == ':':
        return -5.51
    if position == 0 and q in DECLARATIONS:
        return -0.85
    if q and q.strip('·') == '' and len(q) > 1:
        return 0.78
    if q in FORMATS and previous.endswith('%'):
        return 1.54
    if q == 'EOF' and p in {"'", '<<', '<<<'}:
        return 2.58
    if q == 'n' and p.endswith('\\') and any(c in p for c in '{('):
        return 0.30
    if not q or any(c.isalnum() for c in q):
        return 0.0

    # An escaped backslash in code is unlike a TeX row separator.
    if '\\\\' in s:
        if math or p == '}}' or spaced and p[-1:].isdigit():
            return -1.97
        if '"' in previous and '(' in previous:
            return 2.63
        return 0.45 if spaced else 1.27
    if '\\' in s:
        if '{' in s:
            return (1.64 if p.endswith(('=', ':')) else 1.05) if spaced else 0.21
        if '*' in s:
            return 1.48
        if '_' in s:
            return 0.65
        if '"' in s:
            if '\\\\' in previous:
                return 1.52
            return 0.27 if spaced or '(' in s + previous or '\\' in previous else 0.0
        return 0.2 if any(c in s for c in '$[/:(') else 0.0

    # Literal/list openings are stronger than blocks following a condition.
    brace = s.rfind('{') > s.rfind('}')
    if '\n' in s:
        if brace:
            if s.count('(') > s.count(')'):
                return 1.49
            if p.endswith(('=', ':')) or p in {'return', 'struct'}:
                return 1.77
            if p.endswith(')'):
                return 0.15
            return 1.25 if not spaced and '\n' in previous else 0.65
        if s.count('(') > s.count(')') or s.count('[') > s.count(']'):
            return 1.21
        return 0.52 if ':' in s and p in {'else', 'try', 'None'} else 0.0
    if brace:
        if '"' in s or "'" in s:
            return 0.67 if spaced else 1.19 if ':' in s else 0.04
        if '(' in s or '[' in s:
            return 0.45
        return -0.62 if p == 'import' else 0.05
    if q.startswith('_') and spaced:
        return 1.17 if p.endswith('_') else 0.47

    # Shell option prefixes and mathematical unary minus.
    if q in {'-', '−', '--'}:
        if p in COMMANDS:
            return 2.17
        if q == '--':
            return 0.80 if spaced else 0.22
        if p.endswith(('=', ':', ',', '<', '(', '{', '≈', '≠', '⇒')) or p == 'is':
            return 0.94 if spaced else 0.36
        if not p or p[-1:].isdigit() or len(p) == 1 or p.endswith((')', ']', '²')):
            return 0.0
        return 0.24 if spaced else 0.0
    if q.endswith('-') and any(c in q for c in '([=,'):
        return 0.41
    if q == '/' and spaced:
        if p in COMMANDS or p == '>':
            return 1.05
        if p[-1:].isdigit() or p.endswith((')', ']')) or len(p) == 1:
            return 0.0
        return 0.32
    return 0.0


def step(carry, prefix, upstream):
    same = (len(prefix.token_ids) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2])
    position = carry + 1 if same and carry is not None else 0
    previous = prefix.token_strings[-2] if same else ''
    s = prefix.token_strings[-1]
    math = False
    if '\\\\' in s:
        t = prefix.position
        recent = ''.join(prefix.token_strings[i]
                         for i in range(max(0, t - 16), t)
                         if prefix.document_ids[i] == prefix.document_ids[-1])
        math = any(macro in recent for macro in TEX)
    return position, predict(s, previous, position, math)

programs.haiku:
"""Argument-opening tokens in code and shell text (layer 1 MLP, component 2058).

The component is near zero on most text. It turns on at a token that opens an
argument, flag, path, format spec or block inside code or a shell command:

- a hyphen flag right after a shell command: `grep -E`, `tail -n`, `cat --help` (strongest);
- a path slash right after a shell command: `find /`, `cat /etc`;
- a hyphen used as a minus after a number or name (`x - 1`) is weak; after punctuation
  or a space (`= -1`, `, -`) it is moderate;
- a letter that is a printf-style conversion after " %" (`%d`, `%s`);
- an opening bracket or brace that ends a line: `(\n`, ` {\n`, ` [\n`, ` {"`;
- an escaped backslash or brace, as in code embedded in a JSON string: `\\`, ` {\\`;
- a few rule and line-drawing tokens: ` _`, `---------`, `EOF` (heredoc marker).

Everything else is 0. The program looks only at the current token and the one
before it, and carries no state.
"""

import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

SHELL_COMMANDS = frozenset(
    "cat grep head tail sed awk ls find python python3 git npm pip make cd docker curl wget "
    "rm cp mv mkdir chmod apt yarn node go cargo pytest bash sh xargs diff sort uniq wc echo "
    "tar ps kill export which sudo pnpm mvn jest".split()
)
FLAG_DASHES = frozenset([" -", " --"])
LINE_OPENERS = frozenset([" {\n", "{\n", " (\n", "(\n", " [\n", "[\n", "({\n", " [{", " {\"", "({"])
DOUBLE_BACKSLASHES = frozenset(["\\\\", "\\\\\\\\"])
ESCAPES = frozenset([" {\\", "*\\", "{\\", " \\\"", "\\\"", "\\/", "\\_"])
RULE_TOKENS = frozenset([" _", "---------", "----------", "··", "EOF"])


def step(carry, prefix, upstream: Mapping):
    cur = prefix.token_strings[-1]
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    word = prev.strip()
    after_command = word in SHELL_COMMANDS
    if cur in FLAG_DASHES:
        if after_command:
            return carry, 2.2
        if re.search(r"[\w)\]]$", word):
            return carry, 0.15
        return carry, 0.6
    if cur == " /":
        return carry, 1.1 if after_command else 0.25
    if cur in DOUBLE_BACKSLASHES:
        return carry, 1.3
    if prev == " %" and len(cur) == 1 and cur.isascii() and cur.isalpha():
        return carry, 1.6
    if cur in LINE_OPENERS or cur in ESCAPES:
        return carry, 0.6
    if cur in RULE_TOKENS:
        return carry, 0.9
    return carry, 0.0

programs.sol:
"""A formatting-sensitive delimiter and whitespace signal.

Closing brackets on indentation-only lines are negative, unlike spaced inline
closes. Return arrows in function signatures are negative as well. Whitespace
split across tab/space tokens is strongly positive. A smaller positive estimate
covers Han text immediately following the Chinese numeral one (一).
Ordinary text defaults to zero; finer word-specific variation is not modeled.
"""
import re
import regex

READS = ()
LINE_BREAK = re.compile(r'\n|\\[nr]')
MARGIN = re.compile(r'^\s*(?:\d+[ \t]*[|\t]\s*)?(?:(?:[+|*-]|//)\s*)?$')
SIGNATURE = re.compile(r'\b(?:def|fn)\b')
HAN = regex.compile(r'^\p{Script=Han}')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous = '', ''
    else:
        _, line, previous = carry
    s = prefix.token_strings[-1]
    core = s.lstrip(' \t')
    spaced = s != core
    newline = '\n' in s or '\\n' in s
    margin = bool(MARGIN.fullmatch(line))
    value = 0.0
    if core and core[0] in ')]}':
        close = core[0]
        if margin:
            if close == '}':
                if not spaced and not line:
                    value = -1.0
                elif newline:
                    value = -1.8
                else:
                    value = -2.1 if spaced else -2.5
            elif close == ']':
                value = -3.2 if spaced else (-2.4 if newline else -0.3)
            else:
                if newline:
                    value = -3.2
                elif spaced:
                    value = -2.9
                else:
                    value = -4.3 if line else -1.3
        elif spaced:
            value = {'}': 0.3, ']': 0.2, ')': 0.8}[close]
            if newline or (close == '}' and (',' in core or ';' in core)):
                value = -0.25 if close == '}' else 0.2
        elif close == '}':
            value = -0.12
    if core.startswith('{') and margin and newline:
        value = -0.4 if spaced else -0.15
    if core == '->' and previous.rstrip().endswith(')'):
        if MARGIN.fullmatch(line.rsplit(')', 1)[0]):
            value = -2.8
        elif SIGNATURE.search(line):
            value = -2.2
    if s.isspace() and previous.isspace():
        if s.startswith(' ') and previous.endswith('\t'):
            value = 5.5 if newline else 7.2
        elif s.startswith('\t') and previous.endswith(' '):
            value = 2.5
    if previous.endswith('一') and HAN.match(s):
        value = 1.1 if previous == '一' else 0.2
    line = LINE_BREAK.split(line + s)[-1][-200:]
    return (doc, line, s), value

"""Approximate the component's strongest pattern: nasal-syllable spellings.

Hang/häng is strongly negative, especially when h and ang are separate
tokens. Gang, bang and fang are weaker; tang, some vowel-led ang fragments,
and Chinese 娘 are positive. The preceding letters distinguish these from
unrelated fragments, such as Zhang. Capitals and nominal "the/a hang" get
stronger values. Contiguous short inflections retain a reduced response;
ång and ngh crossing token boundaries have small extra rules.

These are spelling rules with fitted magnitudes, not a semantic account.
Most tokens get zero; document boundaries reset the one-token memory.
"""
import re
import unicodedata

READS = ()

ANG_ONSETS = {
    'h': -8.4, 'g': -3.9, 'f': -2.6, 'b': -2.9,
    'ch': -2.0, 'sh': -2.9, 'th': -2.2, 'zh': -3.8,
    'ph': -4.0, 'j': -1.3, 'k': -0.7,
    'd': 1.4, 't': 0.5, 'w': 0.8, 'l': 0.3,
    'n': 1.7, 'u': 2.5, 'o': 3.0, 'i': 0.9,
}
WHOLE_SYLLABLES = {
    'hang': -5.8, 'hung': -2.8, 'gang': -3.1,
    'bang': -1.8, 'fang': -1.4, 'tang': 0.7,
    'wang': -1.3, 'yang': -0.1,
}


def onset(text):
    text = text.lower()
    for pair in ('ch', 'sh', 'th', 'zh', 'ph', 'kh'):
        if text.endswith(pair):
            return pair
    return text[-1:]


def fragment_value(s, previous):
    if s == '娘':
        return 3.0
    if s in WHOLE_SYLLABLES:
        return WHOLE_SYLLABLES[s]
    if s in ('hangs', 'hanging'):
        return -4.9
    # German umlaut is significant; Vietnamese tone marks are not removed
    # here, except in the two familiar h-initial nasal syllables.
    unaccented = ''.join(c for c in unicodedata.normalize('NFD', s)
                          if not unicodedata.combining(c))
    if s != unaccented and unaccented in ('hang', 'hanh'):
        return -3.5 if unaccented == 'hang' else -1.6
    m = re.fullmatch(r'(ang|äng|eng|ing|ung)(s|e|en|er|ers|ed|an|a|kan)?', s)
    if m:
        vowel, suffix = m.groups()
        initial = onset(previous)
        if vowel == 'ang':
            value = ANG_ONSETS.get(initial, 0.0)
            if suffix in ('er', 'ers'):
                value = {'h': -10.7, 'g': -6.2, 'b': -6.5}.get(initial, value)
            return value
        if vowel == 'äng':
            return {'h': -7.3, 'g': -4.1, 'f': -2.6, 'm': -0.6}.get(initial, 0.0)
        if vowel == 'eng':
            return {'h': -5.3, 'g': -2.1, 'f': -1.0,
                    'sh': -1.7, 'ch': -1.5, 'zh': -0.7}.get(initial, 0.0)
        if vowel == 'ung':
            return -1.5 if initial == 'h' else -0.1
        return -1.0 if initial == 'h' else -0.04
    if s == 'iang':
        return 1.7
    if s == 'uang':
        return -3.2 if onset(previous) == 'h' else 2.0
    if s == 'anh':
        return 3.1 if previous.endswith('o') else 0.1
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, previous, last = carry
    raw = prefix.token_strings[-1]
    s = raw.strip().lower()
    joined = not raw[:1].isspace()
    context = previous.lower() if joined else ''
    value = fragment_value(s, context)
