        # than the usual verbal hang. Capitals also have a larger response.
        if joined and context.endswith('z'):
            value = 0.0
        elif previous.lower().strip() in ('the', 'a', 'over'):
            value = -8.4
        elif raw.strip()[:1].isupper():
            value = -7.3
    if s in ('ng', 'ngen') and context.endswith('å'):
        value = -2.8
    if s == 'gh' and context.endswith('n'):
        value = -2.7
    if value is None:
        value = 0.0
    return (doc, raw, value), float(value)

