READS = ()


def initial_pulse(text):
    word = text.strip()
    if text.startswith('<|'):
        return -5.2
    if not word:
        return -2.9 if '\t' in text else -0.5
    if '\n' in text or '\r' in text:
        return -1.1
    if '\ufffd' in text:
        return -3.0
    if word.isdecimal():
        return -3.5 if int(word) < 3 else -0.9
    if word.isalpha():
        if not word.isascii():
            return -5.2
        value = -4.1 - 0.73 * (min(len(word), 5) - 1)
        if text.startswith(' '):
            value += 1.6
        if len(word) > 1 and word.istitle():
            value += 0.6
        if zipf_frequency(word, 'en') >= 3:
            value -= 0.73
        return value
    if not any(c.isalnum() for c in word):
        return -2.7
    return -4.4


