    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        pulse = initial_pulse(prefix.token_strings[-1])
        carry = (doc, token, True, pulse)
    else:
        _, first_token, still_same, pulse = carry
        carry = (doc, first_token, still_same and token == first_token, pulse)
    return carry, carry[3] if carry[2] else 0.0

