            value = 2.2
        elif p.endswith('we') and t.startswith('g'):
            value = 6.8
        elif p.endswith(('ve', 'vä')) and t == 'g':
            value = 3.7
        elif p.endswith('we') and t.startswith('av'):
            value = 4.1
        elif p.endswith('w') and t.startswith('ov'):
            value = 3.7
        elif p.endswith('we') and t.startswith('ve'):
