"""layers.1.mlp.down_proj:2064 -- a sparse "year-digit / text-start / path" detector.

What it does, in plain terms:

1. Start of a text segment. At the first token of a row, and at the first token after
   <|endoftext|> (a new document), the component is pushed negative, by how the token
   looks: code or markup starts ("#", "//", "import", "package", ...) most strongly
   (about -5, and -9.5 for "#"); whitespace and lower-case word fragments about -2 to -3.5;
   capitalised words about -1; digits about -1.

2. Years. The second digit of a four-digit year that starts a standalone number,
   "9" after "1" in "1995" or "0" after "2" in "2010", fires positively (about 1 to 4).
   It is stronger in running prose with dates or citations ("in 19..", "born 19..",
   "June 19..", "et al., 19..") and weaker in arithmetic or tables ("=", "+", runs of spaces).
   A digit just before the "1" or "2" (as in "120") gives a small negative value.

3. Unix paths. The directory names "workspace", "usr", "opt", "local", "tmp", "root",
   "home", "etc", "lib" right after a slash (or as "/workspace" tokens) fire at about +2.5.

Everything else is 0. The program is a rule list; it has no table of learned weights.
"""

READS = ()
DIGITS = set("0123456789")
# Words that make a year look like running prose: dates, "born in", citations.
DATE_WORDS = {"in", "born", "since", "from", "during", "et", "al",
              "January", "February", "March", "April", "May", "June", "July",
              "August", "September", "October", "November", "December"}
# Tokens that suggest arithmetic, code or a table rather than prose.
MATH_TOKENS = {" =", "=", " +", "  ", "   ", " is", " that"}
# Tokens that start a code or markup line (weakly negative first tokens).
CODE_START = {"##", "//", "/*", "/*\n", '"""\n', "#include", "import", "package", "int",
              "print", "String", "string", "user", "theorem", "var", "<?", "---\n", "#!/",
              "\\t", "**"}
PATH_DIRS = {"workspace", "usr", "opt", "local", "tmp", "root", "home", "etc", "lib", "Volumes"}
PATH_TOKENS = {"/" + name for name in PATH_DIRS}


def start_value(token):
    """Activation at the first token of a text segment (row start or after <|endoftext|>)."""
    if token == "#":
        return -9.5
    if token in CODE_START or token[:1] in "#/\\*\t\"'":
        return -5.0
    if token.isspace():
        return -3.5
    if token[:1].isspace():
        return -3.0
    if token[:1] in ".,:);]}!?-":
        return -2.6
    if token[:1].isupper():
        return -1.1
    if token[:1].isdigit():
        return -0.9
    return -2.1


def year_value(toks, t):
    """The second digit of a year that starts a standalone number ('9' in 1995, '0' in 2010)."""
    recent = toks[max(0, t - 12):t - 1]
    v = 1.7
    if toks[t - 2] in (" ", " (", "("):  # the number starts a token group
        v += 0.5
    if any(x in DATE_WORDS for x in recent):
        v += 0.4
    if toks[t] == "9":  # '19' is a little stronger than '20'
        v += 0.4
    if any(x in MATH_TOKENS for x in recent):
        v -= 1.3
    if toks[t - 2] in (",", ".", "-", ":", "/"):
        v -= 0.4
    return max(0.0, v)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = prefix.position
    cur = toks[-1]
    if t == 0:
        return None, start_value(cur)
    prev = toks[-2]
    if prev == "<|endoftext|>":
        return None, start_value(cur)
    if cur in PATH_TOKENS or (cur in PATH_DIRS and prev.endswith("/")):
        return None, 2.5
    if t >= 2 and ((cur == "9" and prev == "1") or (cur == "0" and prev == "2")):
        if toks[-3] in DIGITS:  # inside a longer number, as in "120"
            return None, -0.4
        return None, year_value(toks, t)
    return None, 0.0

