"""A category-and-subtype signal.

Small word lists recognize category names. Contrastive modifiers boost
them ('different types', 'a new generation'). The following 'of' or a
subtype's letter/number gets a stronger prediction. Chinese category
words and numbered generations follow the same idea. Code-like uses of
'class' and 'type' are downweighted. Other tokens default to zero; this
approximates the main positive pattern, not every fluctuation.
"""
import re

READS = ()

# Related kinds of category names, with the signal on their following 'of'.
CATEGORY_GROUPS = (
    ('species subspecies', 5.3),
    ('type subtype class category genus', 3.4),
    ('generation gen', 2.0),
    ('strain breed genre grade', 2.5),
    ('kind sort style mode manner variety', 1.7),
    ('version edition revision iteration', 1.6),
    ('form model family subfamily branch subset cluster group', 1.2),
    ('level stage phase tier rank division degree', 1.1),
    ('round wave', 1.8),
    ('size color colour pattern profile format structure design', 0.6),
)
CATEGORY_OF = {w: value for words, value in CATEGORY_GROUPS
               for w in words.split()}
MODIFIER = re.compile(
    r'\b(different|various|several|many|specific|particular|certain|'
    r'new|newer|another|other|special|common|distinct|unique|own|same|related|'
    r'subsequent|latter|successful|first|second|third|next|last|fourth|fifth|'
    r'two|three|four|five|six|all)(?:\s+[a-z]+){0,2}\s*[-]?\s*$',
    re.I,
)
LAST_WORD = re.compile(r'\b([A-Za-z]+)[ -]*$')
ORDINAL = re.compile(r'\b[0-9]+(?:st|nd|rd|th)[ -]*$', re.I)


def singular(word):
    if word in {'species', 'subspecies', 'genus'}:
        return word
    if word.endswith('ies'):
        return word[:-3] + 'y'
    if word.endswith('sses'):
        return word[:-2]
    if word.endswith('s') and not word.endswith('ss'):
        return word[:-1]
    return word


def predict(token, history):
    word = token.strip().lower().lstrip('-')
    root = singular(word)
    value = 0.0
    if root in CATEGORY_OF:
        value = 0.12 + 0.25 * (root != word)
        if MODIFIER.search(history):
            value += 0.9
        if root in {'species', 'subspecies', 'genus', 'family'}:
            value = 0.0
        if root in {'style', 'genre', 'strain', 'breed'}:
            value += 0.4
        if ORDINAL.search(history):
            value += 2.0
        if root in {'generation', 'gen'}:
            value += 0.6
            if MODIFIER.search(history):
                value += 2.0

    match = LAST_WORD.search(history)
    prior_word = match[1].lower() if match else ''
    prior = singular(prior_word)
    if prior in CATEGORY_OF:
        if word in {'of', 'de', 'di', 'd', 'von'}:
            value = CATEGORY_OF[prior]
            modified = MODIFIER.search(history[:match.start(1)])
            if modified and prior not in {'species', 'subspecies', 'genus',
                                           'stage', 'round'}:
                value += 0.5 if prior in {'type', 'subtype'} else 1.4
            if prior in {'generation', 'gen'} and modified:
                value += 1.6
            if prior == 'variety' and prior_word == 'variety':
                value = 0.4
        elif token == ' ':
            if prior in {'type', 'subtype', 'class', 'category', 'group',
                         'grade', 'level'}:
                value = 1.7
            elif prior in {'version', 'form', 'stage', 'phase'}:
                value = 0.5
        elif re.fullmatch(r'[0-9]+|[A-Z]|[IVX]+', token.strip()):
            label = token.strip()
            roman = bool(re.fullmatch('[IVX]+', label))
            number = label.isdigit()
            if prior in {'type', 'subtype'}:
                value = 6.0 if roman or number else (3.5 if label in 'ABC' else 1.0)
                if prior_word.endswith('s'):
                    value *= 0.6
            elif prior in {'class', 'category'}:
                value = 5.0 if roman or label in 'ABC' else 2.0
            elif prior == 'group':
                value = 2.2 if number else 4.0
            elif prior in {'grade', 'stage', 'phase', 'division'}:
                value = 4.5 if roman else 2.7
            elif prior == 'level':
                value = 1.7
            elif prior == 'version':
                value = 1.3
            elif prior in {'form', 'style', 'mode'}:
                value = 0.8

    # Downweight code-like declarations and compound/command names.
    if prior == 'class' and re.search(
            r'(?:^|\n)[ \t]*(?:[0-9]+[ \t]+)?'
            r'(?:(?:public|private|static|abstract|export)\s+)*class[ -]*$',
            history):
        value = 0.0
    if prior in {'type', 'class'} and re.search(
            r'[:\w]-?(?:types?|class)[ -]*$', history):
        value *= 0.15

    # Category, kind, model, version, rank: Chinese equivalents.
    if word in {'型', '类型', '類型', '类', '類', '类别', '類別', '种类', '種類'}:
        value = 1.1
    elif word in {'种', '種', '各种', '各種', '这种', '這種', '版本',
                  '版', '款', '系', '系列', '级', '級', '派', '族'}:
        value = 0.65
    if word in {'型の', '種の', '类别的', '類別的', '类型的', '類型的'}:
        value = 2.5
    if word in {'tipo', 'tipos', 'classe', 'clase', 'categoria'}:
        value = 0.65
    if word in {'de', 'di'} and prior_word in {
            'tipo', 'tipos', 'classe', 'clase', 'categoria'}:
        value = 2.4
    if word in {'typeof', 'instanceof', 'isinstance'}:
        value = 0.7
    if word == '代' and re.search(r'第[一二三四五六七八九十0-9]+$', history):
        value = 5.8
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, history)
    return (doc, (history + token)[-100:]), value

