    elif ending.endswith((',', ':', '?', '，', '？')):
        value = 0.78
    elif ending.endswith(';'):
        value = 1.11
    elif ending.endswith('}'):
        value = 1.35
    elif ending.endswith('{'):
        value = 0.98
    elif ending.endswith((')', ']')):
        value = 1.10
    elif ending.endswith('>'):
        value = 1.46
    elif ending.endswith('`'):
        value = 1.19
    else:
        value = 1.26

    value += 0.19 * min(token.count('\n') - 2, 2)
    value += 0.09 * ('\r' in token)
    value -= 0.05 * (bool(body) and token.startswith(' '))
    value -= 0.014 * min(math.log1p(len(line)), 6)
    letters = [ch for ch in line if ch.isalpha()]
    uppercase = sum(ch.isupper() for ch in letters)
    if len(letters) > 2 and uppercase > .8 * len(letters):
        value += 0.25
