LAST_WORD = re.compile(r'([^\W\d_]+)[^\w]*$')
NOT_NAMES = set('''it this that there he she they we you i what which who one
    yes no however therefore thus hence instead otherwise indeed also then
    well wait remember note hmm ok okay so since because although though
    after before during given while if unless'''.split())
