    # ordinary use, after a comma, extra after a capitalized noun
    'which': (0.77, 3.7, 0.9),
    'who': (0.30, 4.5, 2.7),
    'where': (0.37, 1.8, 1.1),
    'whose': (0.05, 2.7, 1.1),
    'whom': (1.0, 5.5, 1.0),
    'wh': (0.15, 1.0, 0.4),
