    der die das welche welcher welches který kter'''.split())
ARTICLES = {'a', 'an', 'the', 'another'}
FOREIGN_ARTICLES = {'un', 'une', 'uno', 'una', 'ein', 'eine'}
COPULAS = {'is', 'are', 'was', 'were', 'be', 'been', 'being'}


@lru_cache(maxsize=8192)
def name_like(word):
    return (len(word) > 1 and word[0].isupper()
            and word.lower() not in NOT_NAMES
            and 'adverb' not in wordnet.parts_of_speech(word.lower()))


