                value = {'a': 4.0, 'an': 5.0, 'the': 1.5, 'another': 3.0}[raw]
            else:
                value = {'a': 0.6, 'an': 1.2, 'the': -0.12, 'another': 1.0}[raw]
        elif opening:
            value = 2.65 if raw == 'the' else 0.5 + 0.3 * named
        elif dash:
