"""Activation of one MLP component in layer 1 (down_proj unit 2078), predicted from the text.

What it responds to, in plain terms:
- Assignment operators. The strongest response is to ' =' right after a newly
  declared name (`const tests =`, `let mut size =`, `List<File> files =`): about +0.7.
  ' =' starting a bare name at the start of a line, or after a type name, gives about +0.35;
  ' =' after some other word about 0; ' =' after a member access (`obj.field =`) or
  after punctuation is ~0 or negative; ' =' opening a line of compiler-note gutter text is -0.45.
  The assignment-like operators ' :=' (Go) and ' <-' (R, Haskell) also fire, at +0.36 and +0.44.
- The first token of every document (where the attention context is just itself) is
  negative, about -0.2.
- Indentation made of a tab followed by spaces: deep alignment (12+ spaces) is positive
  (+0.3), shallow (1 to 4 spaces) is negative (-0.2), in between is small.
- A run of 9 or more plain spaces is mildly positive (+0.1).
Everything else is near zero; that unexplained part is most of the variance.
"""
import re

READS = ()

ASSIGN_OPS = {" :=": 0.36, " <-": 0.44}


def eq_value(line):
    """Value of a ' =' token, given the text of its line before it."""
    if re.fullmatch(r"[\s|]*", line):
        return -0.45
    if re.search(r"\b(const|let|var|val|final|auto|mut)\s+\w+$", line):
        return 0.7
    if re.search(r"\.\w+$", line):
        return 0.0
    if re.search(r"^\s*(?:[\w<>\[\]]+\s+)*\w+$", line):
        return 0.35
    if re.search(r"\w$", line):
        return 0.02
    return -0.08


def indent_value(tok):
    """Value of a tab followed by n spaces, by how deep the indentation is."""
    n = len(tok) - 1
    if n <= 4:
        return -0.2
    if n <= 8:
        return 0.05
    if n <= 11:
        return 0.16
    return 0.3


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    line = "" if new_doc or carry is None else carry
    if new_doc:
        value = -0.2
    elif tok == " =":
        value = eq_value(line)
    elif tok in ASSIGN_OPS:
        value = ASSIGN_OPS[tok]
    elif re.fullmatch(r"\t +", tok):
        value = indent_value(tok)
    elif re.fullmatch(r" {9,}", tok):
        value = 0.1
    else:
        value = 0.0
    line = re.split(r"\\n|\n", line + tok)[-1][-80:]
    return line, value

