"""Mainly a Chinese degree/intensity signal, strongest on 很 ('very').

Fusing it with an adjective or surrounding grammar weakens the response.
Scalar adjectives following degree words also respond. Smaller separate
rules cover Vietnamese/English 'very', the negative acronym ending HC,
a document-initial Title: header, and alternating ordinary/nonbreaking spaces.
Other text is quiet. UTF-8 decoding and context reset at document boundaries.
"""
import codecs
import regex as re

READS = ()

# The strength varies with the kind of complement of 'very'.
# Most simple adjectives share a response; these complement classes differ.
VERY_COMPLEMENTS = {
    '多': 3.2,       # many
    '有': 5.6,       # have
    '是': 3.9,       # be
    '长': 6.7, '長': 6.7,
    '高': 3.8, '低': 3.0,
    '少': 2.5, '差': 2.6,
    '棒': 1.0,       # excellent
}
SIMPLE_COMPLEMENTS = set('好多有是大快长長久难難强強高低少差棒深')
SCALARS = set(
    '大小多少高低长長短远遠近深浅淺久晚快慢'
    '难難易强強弱轻輕重宽寬窄好坏壞'
)
