                    return 4.5
                if before.endswith('很'):
                    return 3.5
                if before.endswith('不') and s[0] == '快':
                    return 0.7
                if s[0] in '久晚快远遠':
                    return 3.3
                return 2.0
    if len(s) >= 2 and s[-1] in SCALARS:
        if s[:-1] in ('更', '较', '較', '比较', '比較', '极', '極', '一'):
