"""Document-start detector with a size per token.

The component is silent everywhere except on the first token of a document: the token right after
<|endoftext|> (or the first token of a packed row). There its activation is set by what that token
looks like, and it does not depend on the text before it:
  - all-caps words (BACKGROUND, NULL, FIELD, THE) and sentence-opening determiners/pronouns
    (The, the, a, This, I, You, We, They, What) push it up, most for all-caps;
  - opening brackets, quotes, '#' and '<' (code and markup starts) push it up;
  - other capitalised words push it up a bit, other lowercase words a little less;
  - grammatical glue (of, in, for, is, was, by, ...), digits, line breaks, '.' and blank runs push it down.
"""
READS = ()

END_OF_TEXT = "<|endoftext|>"
GLUE = {"of", "in", "on", "for", "from", "by", "at", "as", "is", "was", "are", "be", "were"}
DETERMINERS_PRONOUNS = {"the", "a", "an", "this", "these", "i", "you", "we", "they", "he", "she", "my", "what", "how", "there", "here"}
OPENERS = set("({[<\"#*“")


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[t]
    starts_document = t == 0 or prefix.token_strings[t - 1] == END_OF_TEXT
    if not starts_document:
        return None, 0.0
    word = token.strip()
    if not word:
        return None, -1.0
    if word.lower() in DETERMINERS_PRONOUNS and word != "A":
        return None, 4.0
    if word.lower() in GLUE:
        return None, -0.7
    if word[0].isdigit() or word[0] in "\n.。":
        return None, -0.5
    if word.isupper() and len(word) > 1:
        return None, 6.0
    if word[0] in OPENERS:
        return None, 3.3
    if word[0].isupper():
        return None, 2.5
    return None, 1.5

