import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
PREPOSITIONS = {
    'für': 1.0, 'для': 0.70, 'dla': 0.80, 'för': 1.2,
    'voor': 0.53, 'pentru': 0.94,
}


@lru_cache(maxsize=10000)
def frequency(word, language):
    return zipf_frequency(word, language)


def language_score(text, language):
    words = re.findall(r"[^\W\d_]+", text.lower())[-16:]
    return sum(frequency(w, language) for w in words) / max(1, len(words))


