    readiness = {
        'ready', 'grateful', 'responsible', 'suitable', 'available', 'true',
    }
    if low in readiness:
        value = 0.12
    if bases & {'design', 'intend', 'prepare'}:
        value = 0.35
    if low in {'be', 'is', 'are', 'was', 'were', 'been', 'being'}:
        value = 0.38
    if len(low) == 1:
