"""Component layers.1.mlp.down_proj:2085 -- a "day 30 / day 31" detector.

It fires on the second digit of a two-digit number that reads 30 or 31, most strongly when
the number follows a month name ("September 30", "June 31"). It is weaker when the number is
part of a longer digit run ("2030", "130") and when there is no month before it. Side cases
also fire: the word "thirty", NUL bytes (the padding of UTF-16-style text, one NUL per
character) and a pair of middle dots (fill characters in tables). Everything else is silent.
"""

import re

READS = ()

MONTH_END = re.compile(
    r"(January|February|March|April|May|June|July|August|September|October|November|"
    r"December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\.?\s$"
)


def _is_digit(tok):
    return len(tok) == 1 and tok.isdigit()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    now = toks[-1]
    doc = docs[-1]

    # Side cases: null bytes, middle-dot fill, the word thirty.
    if now == "\x00":
        return carry, 0.7
    if now == "··":
        return carry, 0.9
    if now.strip().lower() == "thirty":
        return carry, 0.9

    # Two-digit number "3" then "0" or "1", within the same document.
    if len(toks) < 2 or now not in ("0", "1") or toks[-2] != "3":
        return carry, 0.0
    if docs[-2] != doc:
        return carry, 0.0

    value = 1.2 if now == "0" else 0.8  # "30" is stronger than "31"
    # A '3' inside a longer digit run ("2030") is weaker.
    if len(toks) >= 3 and _is_digit(toks[-3]) and docs[-3] == doc:
        value *= 0.4
    # A month name right before the number boosts it.
    before = []
    for i in range(len(toks) - 3, max(-1, len(toks) - 12), -1):
        if docs[i] != doc:
            break
        before.insert(0, toks[i])
    if MONTH_END.search("".join(before)):
        value *= 2.0
    return carry, float(value)

