FUNCTION_WORDS = frozenset('''a an the this that these those i you he she it we
 they me him her us them my your his its our their who whom whose which what
 some any no each every all both few many more most other such can could will
 would may might shall should must do does did have has had be am is are was
 were been being not also very much too just only to of for from with at by on
 in into over under than as if or and but so then there here when where how why
 '''.split())
DAY_PARTS = {'morning', 'afternoon', 'evening', 'night'}
WEEKDAYS = {s.lower() for s in calendar.day_name}
ACADEMIC = {'school', 'college', 'university'}
SPORT_QUALIFIERS = ACADEMIC | {'youth', 'professional', 'ncaa', 'nfl'}
BUILDING_PARTS = {'door', 'floor', 'wall', 'roof', 'ceiling', 'window',
                  'insulation'}
Features = namedtuple('Features', 'noun sport room tissue subject')


@lru_cache(maxsize=50000)
def describe(word):
    return Features(
        noun='noun' in wordnet.parts_of_speech(word),
        sport=wordnet.is_a(word, 'athletics'),
        room=wordnet.is_a(word, 'room') or wordnet.is_a(word, 'building'),
        tissue=(wordnet.is_a(word, 'animal tissue')
                or wordnet.is_a(word, 'plant tissue')
                or 'tissue' in wordnet.base_forms(word, 'noun')),
        subject=(wordnet.is_a(word, 'science')
                 or wordnet.is_a(word, 'mathematics')),
    )


@lru_cache(maxsize=100000)
def compound_response(previous, current):
    p, c = previous.strip().lower(), current.strip().lower()
    if not current.startswith(' '):
        return 0.0
    if not all(w.isascii() and w.isalpha() and w not in FUNCTION_WORDS
               for w in (p, c)):
        return 0.0
    before, head = describe(p), describe(c)
    value = 0.0
    if wordnet.parts_of_speech(p + ' ' + c):
        value -= 0.034
    if head.sport:
        value -= 0.116
    if head.noun and (before.sport or p in {'sports', 'athletic'}):
        value -= 0.115
    if head.noun and before.room:
        value -= 0.051
    if head.tissue:
        value -= 0.072
    if (p in {'personal', 'private', 'corporate'}
            and c in {'data', 'information', 'finance', 'security'}):
        value -= 1.338
    if ((p in WEEKDAYS and c in DAY_PARTS)
            or (p in DAY_PARTS and c in {'sun', 'sky', 'sunshine'})):
        value -= 1.158
    if p in ACADEMIC and head.subject:
        value -= 1.202
    if p in SPORT_QUALIFIERS and head.sport:
        value -= 1.196
    if p == 'sports' and head.noun:
        value -= 0.693
    if before.room and BUILDING_PARTS.intersection(
            wordnet.base_forms(c, 'noun')):
        value -= 1.649
    if (head.noun and p in {'territorial', 'government', 'local'}
            and (c == 'entity' or wordnet.is_a(c, 'geographical area'))):
        value += 0.312
    if head.noun and p in {'financial', 'economic'}:
        value += 0.159
    return value


def step(carry, prefix, upstream):
    t = prefix.position
    s = prefix.token_strings[-1]
    same_doc = t > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]
    previous = prefix.token_strings[-2] if same_doc else ''
    initial_title = previous == 'Title' and (
        t == 1 or (t > 1 and (
            prefix.document_ids[-2] != prefix.document_ids[-3]
            or prefix.token_strings[-3] == '<|endoftext|>')))
    if s == ':' and initial_title:
        return None, 6.609
    if len(s) >= 2 and set(s) == {'·'} and set(previous) == {'·'}:
        return None, 1.297
    baseline = 0.0011 if same_doc else 0.0844
    return None, baseline + compound_response(previous, s)

"""Approximate multilingual adverb morphology from the current partial word.

Split Romance -ment(e) endings usually receive strong negative predictions.
Frequency comparisons and adjective cognates help reject lookalike nouns;
some discourse adverbs receive weaker predictions. Additional rules cover
Nordic, Polish, Czech and German endings. Selected English manner and degree
adverbs receive positive predictions. Other split -ment endings get a small
positive baseline; unrecognized cases default to zero.

These are surface rules, not a full parser or a model of contextual variation.
The partial word resets at document boundaries.
"""
import re
import wordnet
from anyascii import anyascii
from functools import lru_cache
from wordfreq import zipf_frequency as frequency

READS = ()
CARE = {'accurately', 'adequately', 'carefully', 'closely',
        'meticulously', 'selectively'}
DELIBERATE = {'properly', 'truly', 'greatly', 'seriously', 'gently', 'tightly'}
FRENCH_ENDINGS = (
    'amment', 'emment', 'iquement', 'ivement', 'alement', 'ellement',
    'ablement', 'iblement', 'airement', 'ièrement', 'eusement',
    'ennement', 'ieurement', 'érieurement', 'oirement', 'quement',
)
DISCOURSE = {'évidemment', 'notamment', 'heureusement', 'malheureusement',
             'apparemment', 'suffisamment', 'récemment'}
NORDIC_ENDINGS = {'t', 'igt', 'ligt', 'ellt', 'elt', 'rt', 'lt',
                  'gt', 'vt', 'amt', 'igen', 'elig'}

@lru_cache(maxsize=16384)
def frequencies(word):
    return {l: frequency(word, l) for l in
            ('en', 'fr', 'de', 'es', 'pt', 'it', 'sv', 'nb', 'da')}

# French adjective bases that are not ordinary English cognates.
FRENCH_BASES = {
    'libre', 'parfaite', 'aucune', 'bonne', 'soudaine', 'étroite',
    'haute', 'ouverte', 'absolu', 'brève', 'briève', 'brieve', 'aisé',
    'sûre', 'mûre', 'commun', 'perfide', 'efficace', 'égale',
    'difficile', 'légère',
}

@lru_cache(maxsize=8192)
def french_adverb(word):
    if 'noun' in wordnet.parts_of_speech(anyascii(word)):
        return False
    stem = word[:-4]
    if stem in FRENCH_BASES:
        return True
    # French feminine -e often masks a shared English adjective.
    base = anyascii(stem)
    candidates = {base, base[:-1] if base.endswith('e') else base}
    if base.endswith('ue'):
        candidates.add(base[:-2])
    # Very short strings also match letters and Roman numerals in WordNet.
    if any(len(x) >= 4 and 'adjective' in wordnet.parts_of_speech(x)
           for x in candidates):
        return True
    if word.endswith('ément') and len(stem) >= 5:
        return frequency(stem, 'fr') > 1.5
    return word.endswith(FRENCH_ENDINGS) and frequency(stem + 'r', 'fr') < 2.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    match = re.search(r'[^\W\d_]+\Z', old + token)
    word = match.group().lower()[-80:] if match else ''
    attached = bool(old) and token.isalpha()
    value = 0.0
    if word.endswith(('ment', 'mente')):
        f = frequencies(word)
        romance = max(f['es'], f['pt'], f['it'])
        if word.endswith('mente') and len(word) > 7:
            if romance > max(f['de'], f['en'], f['fr']) or not max(f.values()):
                if token in {'e', 'ente'} and attached:
                    if romance > 1.0 and (token == 'ente' or
                                           french_adverb(word[:-1])):
                        value = -6.0
                else:
                    value = -4.0 if attached else -1.6
        elif word.endswith('ment'):
            french = (f['fr'] > max(f['en'], f['de']) + 0.3 or
                      (0 < f['fr'] and f['en'] < 2.0 and f['de'] < 1.5
                       and french_adverb(word)))
            if french:
                if word in DISCOURSE:
                    value = -0.6
                elif french_adverb(word):
                    if not attached:
                        value = -1.0
                    elif len(token) <= 6 or token in {
                        'atement', 'irement', 'urement', 'acement'
                    }:
                        value = -4.6
                    else:
                        value = -2.6
                elif attached:
                    value = -0.7
            elif attached:
                value = 0.3
    elif attached and token in NORDIC_ENDINGS and len(word) > 3:
        f = frequencies(word)
        nordic = max(f['sv'], f['nb'], f['da'])
        if nordic > max(f['en'], f['de']) + 0.3 and nordic > 1.5:
            if token in {'igt', 'igen'}:
                value = -3.0
            elif token == 't':
                if word.endswith(('iskt', 'ivt', 'ellt', 'alt',
                                  'amt', 'omt', 'remt')):
                    value = -2.5
                elif word in {'langt', 'långt', 'snabbt', 'raskt'}:
                    value = -2.5
            else:
                value = -1.5
    elif attached and token in {'nie', 'cznie'} and len(word) > 4:
        value = -3.0 if word.endswith('alnie') else -0.8
    elif attached and token == 'ě' and len(word) > 3:
        value = -1.2 if word.endswith('ně') else -0.3
    elif attached and token == 'weise':
        value = -0.8
    elif token.strip().lower() in CARE:
        value = 1.0
    elif token.strip().lower() in DELIBERATE:
        value = 0.5
    return (doc, word), value

