"""Possessive-'s detector: fires on the apostrophe that marks a possessive noun
("the company's", "the veterans' appeals", "Plaintiffs’ employment")."""

READS = ()

# Words before "'s" that make it a contraction ("it's", "that's", "let's") instead of a possessive.
CONTRACTION_HOSTS = {
    "it", "that", "he", "she", "what", "here", "there", "let", "who",
    "where", "how", "this", "which", "when", "why", "everything", "nothing",
}

S_FORMS = {"'s", "’s", "'S", "’S"}
APOSTROPHES = {"'", "’"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        word = prefix.token_strings[-2].strip().lower()
    if tok in S_FORMS:
        # "'s" after a noun is possessive; after a pronoun or "here/there/let" it is "is".
        if word in CONTRACTION_HOSTS or len(word) < 2:
            return carry, 0.0
        return carry, 1.25
    if tok in APOSTROPHES and word.isalpha() and word.endswith("s"):
        # A bare apostrophe after a plural noun ("veterans' appeals").
        return carry, 1.8
    return carry, 0.0

programs.sol:
"""Vowel-less Latin, Cyrillic, and Greek fragments at token boundaries.

A fragment continuing a consonant-ending token gets a positive value. Short
preceding tokens containing a vowel receive larger values, especially before n;
long preceding tokens and tokens without vowels receive less. Separate rules
handle document starts and NUL characters. Most other tokens stay near zero.
These are approximate group means, not individual token-embedding predictions.
"""
from functools import lru_cache
import unicodedata

READS = ()
VOWELS = set('aeiouyøæœıаеёиоуыэюяіїєαεηιουω')


@lru_cache(maxsize=32768)
def describe(text):
    def vowel(ch):
        return any(c in VOWELS for c in
                   unicodedata.normalize('NFD', ch.lower()))

    def consonant(ch):
        name = unicodedata.name(ch, '')
        return (ch.isalpha() and not vowel(ch) and
                any(script in name for script in ('LATIN', 'CYRILLIC', 'GREEK')))

    letters = text.strip()
    cluster = bool(letters) and all(consonant(c) for c in letters)
    tail = 0
    for ch in reversed(text):
        if not consonant(ch):
            break
        tail += 1
    return (letters, cluster, tail, any(vowel(c) for c in text))


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    letters, cluster, _, _ = describe(text)
    previous_letters, _, previous_tail, previous_vowel = describe(previous)

    if text == '\x00':
        value = 0.24 if previous[-1:].isspace() else 1.42
    elif first:
        if text.startswith('<|'):
            value = 0.0
        elif cluster and text == letters:
            value = 0.65
        elif text.isalpha():
            value = 0.46
        else:
            value = 0.32
    elif cluster and text == letters and previous_tail:
        if previous_vowel:
            if len(previous_letters) > 4:
                value = 0.17 if len(letters) > 1 else 0.07
            elif letters in ('n', 'н', 'ν'):
                value = 1.0 if len(previous_letters) <= 2 else 0.65
            elif letters in ('m', 'м', 'μ'):
                value = 0.42
            elif len(letters) > 1:
                value = 0.42 if letters.islower() else 0.24
            else:
                value = 0.29
        elif any('GREEK' in unicodedata.name(c, '') for c in letters):
            value = 0.30
        elif any('CYRILLIC' in unicodedata.name(c, '') for c in letters):
            value = 0.18
        else:
            value = 0.06 if previous.islower() else 0.02
    elif cluster:
        value = -0.03 if len(letters) > 2 else 0.025
    elif text.isalpha() and len(text) > 2:
        value = -0.01
    else:
        value = 0.002
    return (document, text), value

"""A spelling-fragment signal, positive for h--n and negative for intern-.

The h--n response is strongest on short, unspaced fragments of a word,
including German vowel-h-n spellings.  Separately, intern/trainee words
and inter-/extern- continuations give negative responses.  Two common
'in ...' phrases have opposite signs.  Everything else is left near zero.
"""
import re

READS = ()
TRAINEE_WORDS = {'intern', 'interns', 'internship', 'internships'}
TRAINEE_CHINESE = {'实习', '實習', '实习生', '實習生'}
SUFFIXES = {'s', 'ship', 'ships', 'ed', 'ing'}


def activation(token, previous, earlier):
    w = token.strip().lower()
    p = previous.lower()
    if w in TRAINEE_WORDS:
        return -10.7 if 'ship' in w else -7.2
    if token in TRAINEE_CHINESE:
        return -8.2
    if p.strip() == 'intern':
        if w in SUFFIXES:
            return -7.8
        if w in {'a', 'as', 'o', 'os', 'e', 'es', 'i'}:
            return -1.8
    if not token[:1].isspace():
        if p.endswith('int') and w == 'ern':
            return -10.5
        if p.strip() == 'inter' and (w.startswith('n') or w in {'ment', 'red'}):
            return -6.3
        if w.startswith('ern') and p.endswith(('int', 'inn', 'un')):
            return -2.0
    if w == 'extern':
        return -1.3
    if p.strip() == 'in':
        if w in {'turn', 'turns'}:
            if earlier.strip().lower().rstrip(',') == 'which':
                return -4.8
            return -1.4
        if w == 'view':
            return 2.1
    if not token[:1].isspace():
        if re.fullmatch(r'[aeiouäöü]?hn', w):
            if p.endswith('h'):
                return 11.1
            if w == 'ohn' and p.endswith('j'):
                return 1.1
            if w in {'ahn', 'ohn'}:
                if previous[-1:].isupper():
                    return 6.4
                return 3.6
            if w == 'hn':
                return 5.4 if token.islower() else 2.6
            return 2.0
        if w == 'chn':
            return 2.7
        if w.startswith('chn'):
            return 0.4
        if w.startswith('n') and p.endswith('h'):
            if w.startswith('nh'):
                return 11.4
            if p.endswith('ch'):
                return 1.8
            if p.endswith(('ah', 'eh', 'ih', 'oh', 'uh', 'äh', 'öh', 'üh')):
                if w == 'n' and p.endswith(('ah', 'oh', 'äh')):
                    return 7.9
                return 5.9 if len(w) < 4 else 3.0
            if p.strip() == 'h' and (previous.islower() or token.isupper()):
                return 4.4
            if p.endswith('gh') and w == 'n':
                return 5.0
            return 0.8
        if p.endswith('hn') and w in {
            'ung', 'ungen', 'ungs', 'en', 'es', 'lich', 'liche'
        }:
            return 1.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, earlier = '', ''
    else:
        previous, earlier = carry[1:]
    token = prefix.token_strings[-1]
    value = activation(token, previous, earlier)
    return (doc, token, previous), value

