"""Recognize short p--vowel spelling fragments, rather than whole words.

普 ('ordinary/common') is especially positive, weaker in compound tokens;
its unfinished UTF-8 prefix also fires. Pu and split p+u are usually positive,
while split p+os/us and Greek apo- are negative. Script-specific rules cover
related fragments. Most other tokens get zero. Middle-dot runs and an initial
end-of-text marker are separate exceptions. This is only a partial account.
"""
import codecs
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32768)
def roman(text):
    return anyascii(text).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    _, previous, tail, pending = (doc, '', '', b'') if fresh else carry
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'replace', False)
    unfinished = raw[used:]
    state = (doc, text, (tail + text)[-12:], unfinished)
    s, old = text.strip(), roman(previous).strip()
    r, value = roman(s), 0.0
    spaced = text[:1].isspace()

    if s and set(s) == {'·'} and len(s) > 1:
        value = -1.08
    elif s == '<|endoftext|>' and fresh:
        value = 2.59
    if unfinished == '普'.encode()[:2]:
        value = 6.2  # Also matches other Han characters with this prefix.
    elif s.startswith('普'):
        value = (9.3 if pending else 7.8) / len(s)
        if s == '普通话':
            value = 0.55
        elif tail.endswith('朗'):  # As in 特朗普 (Trump).
            value = 1.5
        elif tail.endswith('汤'):  # As in 汤普森 (Thompson).
            value = 3.1
    elif s == '浦':
        value = 2.0
    elif s == 'phổ':  # Vietnamese 'common'.
        value = 2.7

    if s.isascii() and r == 'pu':
        if spaced:
            value = 2.65 if s[0].isupper() else 1.35
        elif previous.endswith('\\'):
            value = 3.7
        else:
            value = -0.2 if previous[-1:].isalpha() else 1.5
    elif spaced and s.isascii():
        if r == 'pus':
            value = -2.4
        elif r == 'pud':
            value = 1.15
        elif r == 'puerto':
            value = 0.56

    # A short preceding fragment makes its final p more salient.
    if old.endswith(('p', 'ph')) and not spaced:
        scale = 1.0 if len(old) <= 3 else 0.35
        if r == 'u' and (not s.isascii() or s == 'u'):
            strength = {'ุ': 2.4, 'ู': 2.4, 'ु': 3.7,
                        'у': 1.2, 'У': 1.2}.get(s, 1.8)
            value = strength * scale
        elif s == 'ос':
            value = -2.2
        elif s.isascii():
            if re.fullmatch(r'u[ae][nr]|udd', r):
                value = 3.5 * scale
            elif r in ('os', 'us') and not old.endswith('ph'):
                strength = -0.25 if old.endswith('rp') else -1.8
                if r == 'us' and old.endswith('up'):
                    strength = -3.2
                value = strength * scale
            elif r in ('un', 'une'):
                value = -0.4 * scale
            elif r == 'app':
                value = -3.4 * scale
            elif r in ('ue', 'ud', 'ou', 'ouch'):
                value = 0.85 * scale

    # Greek p-r and apo- fragments, ignoring accents in preceding text.
    plain = ''.join(c for c in unicodedata.normalize('NFD', tail)
                    if not unicodedata.combining(c))
    if s in ('ο', 'ό', 'ὸ', 'Ο') and plain.endswith(('π', 'Π')):
        value = -1.5 if plain.endswith(('απ', 'Απ')) else (
            -1.4 if s != 'ο' else 0.0)
    elif s == 'ρ':
        if plain.endswith(('πο', 'Πο')):
            value = 2.0
        elif plain.endswith(('π', 'Π')):
            value = 0.55
    elif s == 'ε' and tail.endswith(('π', 'Π')):
        value = 0.3
    elif s == 'р' and tail.endswith('пъ'):
        value = 2.2
    elif s == 'र' and tail.endswith('पु'):
        value = 4.8
    elif r in ('su', 'seu') and old == 'po':
        value = -2.7
    elif s == 'ク' and tail.endswith('プ'):
        value = 0.9
    elif s == '푸' and pending:
        value = 3.4
    return state, float(value)

