from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

ROMANCE_CUES = set(
    'el los las del una unos unas y pero para con por que da das do dos '
    'uma em com não são você ao aos'.split()
)
ENGLISH_CUES = set(
    'the and of to with for is are was were this that from which have has'.split()
)


@lru_cache(maxsize=100000)
def romanized(text):
    return anyascii(text).lower()


@lru_cache(maxsize=100000)
def english(word):
    return zipf_frequency(word.lower(), 'en')


@lru_cache(maxsize=100000)
def romance(word):
    word = word.lower()
    return max(zipf_frequency(word, 'es'), zipf_frequency(word, 'pt'))


def step(carry, prefix, upstream):
