    split_os = bool(
        regex.search(r'[o0]$', previous_piece)
        and regex.match(r'^[-.]?[sz]', piece)
    )
    stem = regex.search(r'[\p{L}\p{M}]+$', previous)
    stem = stem[0] if stem else ''

