JAVA_TOOLS = {
    'jboss': (5.0, 8.3),
    'maven': (2.7, 5.7),
    'junit': (1.9, 4.3),
    'jena': (2.0, 2.8),
    'jdbc': (1.0, 2.1),
    'hamcrest': (2.0, 4.3),
    'springframework': (1.0, 1.2),
    'lombok': (2.4, 0.5),
    'servlet': (1.5, 1.3),
}
