    if token.isspace():
        return -0.25
    if token.strip().isnumeric():
        return -0.33
    if token.startswith(' ') and token.strip().isalpha():
        return -0.06
    if token.isascii() and token.isalpha():
        return -0.29 if token.isupper() else -0.43
    if token.isalpha():
        return -0.15
    if len(token) > 1 and len(set(token)) == 1:
        return -0.9
    return -0.30


def escaped_value(token, previous):
    count = token.count('\\')
    if not count:
        return 0.0
    trailing = len(previous) - len(previous.rstrip('\\'))
    if count >= 4:
        if previous == ' \\':
            return 1.8
        return 1.15 if trailing else 0.55
    if count >= 2:
        if previous == ' \\':
            return 1.3
        if trailing:
            return 0.65
        return 0.65 if '/' in token else 0.10
    if trailing and not any(ch.isalnum() for ch in token):
        if token == '\\"':
            stronger = previous.startswith(' ') or trailing == 1
            return 0.90 if stronger else 0.70
        return 0.40
