"""Activation of layers.1.mlp.down_proj:2104: the auxiliary "do" of do-support.

The unit answers to the auxiliary verb "do" (and the "n't" of "don't"), and how
strongly depends on the words just before it:
  - inside a question opened by a question word ("What do you", "How do I",
    "Which strategies do you", "Why don't we"): very strong;
  - at the start of a clause, after punctuation or "and/or/but/nor" ("Do you...",
    "..., do not"): moderate;
  - after a subject pronoun ("I do", "we don't"): weak;
  - after "to", a modal, or "who" ("to do", "can do", "users who do not"): none,
    since that "do" is a main verb or a relative clause's verb.
"does", "did" and the other auxiliaries barely register.
"""

READS = ()

QUESTION_WORDS = {"what", "how", "why", "where", "when", "which", "long"}
# words that end the search for a question word, or make "do" a main verb
STOP_WORDS = {"can", "could", "will", "would", "should", "must", "may", "might", "did", "does",
              "is", "are", "was", "were", "have", "has", "had", "to", "who", "that"}
# how strongly a "do" fires, by the word before it
DO_AFTER = {
    **{w: 9.0 for w in QUESTION_WORDS},
    "?": 4.7, "or": 4.7, "nor": 4.5, ".": 3.9, "but": 3.1, ",": 3.0, "and": 1.9,
    "i": 0.6, "we": 0.35, "you": 0.3, "they": 0.0,
}
SUBJECTS = {"i", "we", "you", "they"}
# "n't" after "don", by the word before "don"
NT_AFTER_SUBJECT = {"i": 2.0, "you": 1.1, "we": 1.3, "they": 0.4}


def _word(text):
    return text.strip().lower()


def _is_punctuation(word):
    """Punctuation, a line break, or a document boundary token."""
    return word.startswith("<|") or not any(ch.isalnum() for ch in word)


def _in_question(toks, window=8):
    """True if a question word opens the clause the auxiliary is in; toks ends just before it."""
    for tok in reversed(toks[-window:]):
        word = _word(tok)
        if word in QUESTION_WORDS:
            return True
        if _is_punctuation(word) or word in STOP_WORDS:
            return False
    return False


def _do_strength(toks, prev, capitalised=False):
    """Strength of an auxiliary "do" whose preceding tokens are toks (prev is the last)."""
    if prev in STOP_WORDS:
        return 0.0
    if prev in SUBJECTS:
        return DO_AFTER[prev]
    if _in_question(toks):
        return 9.0
    if prev in DO_AFTER:
        return DO_AFTER[prev]
    if _is_punctuation(prev):
        return 4.0 if capitalised else 3.5
    return 0.0


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    raw = toks[-1]
    word = _word(raw)
    prev = _word(toks[-2]) if len(toks) > 1 else ""
    before = _word(toks[-3]) if len(toks) > 2 else ""
    if word in ("do", "dont"):
        return carry, _do_strength(toks[:-1], prev, raw.strip() == "Do")
    if word in ("'t", "’t") and prev == "don":
        if before in NT_AFTER_SUBJECT:
            return carry, NT_AFTER_SUBJECT[before]
        return carry, _do_strength(toks[:-2], before)
    if word == "not" and prev == "do":
        return carry, 0.9
    return carry, 0.0

programs.sol:
"""Sparse TANG/KANG/PANG-like spelling responses, not a general topic detector.

Mandarin readings and tones are qualified by radical: homophones need not agree.
Roman -ang pieces depend on their preceding consonant; ordinary English stems
like entang(le) are excluded. Smaller rules approximate non-past-tense Japanese
ta, Thai ng, Korean ang syllables, and document-initial middle-dot runs. Other
tokens predict zero; low-amplitude lexical and richer context effects are omitted.
"""
import codecs
import re
from functools import lru_cache
import regex
from pypinyin import lazy_pinyin, Style
import unihan

READS = ()


@lru_cache(maxsize=10000)
def han_signature(s):
    if regex.fullmatch(r'\p{Script=Han}', s):
        radical = unihan.radical(s)
        if radical is not None:
            return (lazy_pinyin(s, style=Style.TONE3)[0],
                    unihan.radical_name(radical))
    return None


def activation(text, before, split_character):
    s, last = text.strip(), before[-1:]
    han = han_signature(s)
    if han == ('tang1', 'water'):  # water radical: soup / hot water
        if regex.search(r'[\p{Hiragana}\p{Katakana}]', before):
            return 4.1
        return 8.5 if split_character else 6.2
    if han == ('pang2', 'dotted cliff'):  # broad roof
        return 7.1 if split_character else 4.2
    if han:
        # Tang (dynasty), tang (hall/pond), Kang, Zhuang, and Xia (summer).
        return {
            ('tang2', 'mouth'): 2.2,
            ('tang2', 'earth'): 0.35,
            ('kang1', 'dotted cliff'): 0.6 if last == '健' else 4.3,
            ('zhuang1', 'dotted cliff'): 4.2,
            ('zhuang1', 'grass'): 3.1,
            ('xia4', 'go slowly'): 0.7,
        }.get(han, 0.0)
    if text == 'た':
        # Suppress the common past-tense environments, not lexical TA.
        return 0.0 if last in 'いしっえけげせねべめれみ見来じ' else 1.0
    if text in ('ง', 'ัง', 'ิง'):
        if last == '้':
            return -3.7
        if last in ('ย', 'ง', 'จ'):
            return -2.0
        return -0.6 if text == 'ง' else -0.3
    if s == '탕':
        return 1.5
    if s in ('강', '장') and text.startswith(' '):
        return -0.65
    if 'äng' in s.lower() or 'анг' in s.lower():
        return -0.35
    if not re.fullmatch('[A-Za-z]{1,6}', s):
        return 0.0
    low = s.lower()
    if low in ('ang', 'anga', 'ango', 'angs', 'angen', 'angkan', 'angan'):
        match = re.search('[A-Za-z]+$', before) if text[:1].isalpha() else None
        stem = match.group().lower() if match else ''
        onset = re.search('[bcdfghjklmnpqrstvwxyz]+$', stem)
        onset = onset.group() if onset else ''
        if onset.endswith('t'):
            if (stem + low).endswith(('entang', 'rectang')):
                return 0.0
            return 1.2 if low in ('ango', 'angen') else 3.4
        if onset.endswith('k'):
            return 2.7
        if onset.endswith(('sh', 'th')):
            return 2.0
        if stem.endswith('zhu') or onset.endswith('zh'):
            return 2.5
        if onset.endswith('j'):
            return -2.8 if low in ('ango', 'angan') else -4.0
        if stem.endswith('gel'):
            return -4.4
        if stem.endswith(('gu', 'qu')):
            return -1.5
        if onset.endswith('ng'):
            return -2.8
        return -1.4 if onset.endswith(('g', 'l', 'n', 'y')) else -0.15
    if s in ('Tang', 'Kang', 'Pang'):
        return {'Tang': 3.8, 'Kang': 2.4, 'Pang': 1.4}[s]
    if low == 'tang':
        return 1.0
    if low.endswith('jang'):
        return -2.5
    if low.endswith(('lang', 'gang')):
        if text.startswith(' ') or s[:1].isupper():
            return -0.2
        return -0.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', True)
    _, pending, recent, only_dots = carry
    data = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(data, 'ignore', False)
    only_dots = only_dots and not text.strip('·')
    value = activation(text, recent, bool(pending))
    if text == '··' and only_dots:
        value = 1.15
    return (doc, data[used:], (recent + text)[-80:], only_dots), value

"""Approximate document-onset, token-shape, and issue-markup effects.

The initial token (including an opening run of repetitions) gets a
negative value when alphabetic, especially if long and unspaced.
Later values are small: they depend on spacing,
length, punctuation-prefixed names, and whether the document just began.
The opening <issue_start><issue_comment> markup has a separate positive
response. These rules do not capture the component's irregular lexical
and contextual fluctuations.
"""
READS = ()


def onset_value(token, text):
    if text.isalpha():
        if len(text) <= 3:
            return -0.091 if text.isupper() else -0.168
        return -0.208 if token.startswith(' ') else -0.335
    if len(text) == 1:
        return -0.030 if text.isascii() else -0.177
    return 0.003 if len(text) >= 8 else -0.164


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first, opening_run, tail = (
            0, prefix.token_ids[-1], True, '')
    else:
        _, position, first, opening_run, tail = carry
        position += 1
        opening_run = opening_run and prefix.token_ids[-1] == first

    text = token.strip()
    if opening_run:
        value = onset_value(token, text)
    elif token.startswith(' '):
        if len(text) >= 8:
            value = 0.006
        else:
            value = 0.005 if position < 32 else -0.002
    elif position < 32:
        value = 0.003 if 1 <= len(text) <= 3 else 0.013
    else:
        prefixed_name = (bool(text) and not text[0].isalnum()
                         and any(c.isalpha() for c in text))
        value = -0.019 if prefixed_name else -0.006

    if token == 'issue' and tail == '<issue_start><':
        value = 1.180
    elif token == 'issue' and tail == '<':
        value = 0.252
    tail = (tail + token)[-40:]
    return (doc, position, first, opening_run, tail), value

"""A coarse document-onset and text-delimiter approximation.

Initial tokens, including uninterrupted repetitions, get a negative
baseline, strongest for short bare ASCII words. Declaration, comment,
triple-quote and carriage-return exceptions get positive values instead.
Elsewhere, recognize recent << before EOF and the initial Title: label,
and weakly suppress line endings. Token-specific fluctuations are omitted.
"""
READS = ()


def onset(token):
    if token == '\r':
        return 0.63
    if token == '//\n':
        return 0.75
    word = token.strip()
    if word in {'<!', '@extends'}:
        return 1.75
    if word.startswith(('"""', "'''")):
        return 0.30
    if word in {'/*', '<!--'}:
        return 0.19
    if word.isascii() and word.isalpha():
        if token.startswith(' '):
            return -0.46
        return -0.79 + 0.055 * min(len(word), 6)
    if not word.isascii():
        return -0.44
    return -0.59


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        initial, repeated, history = token, True, ''
    else:
        _, initial, repeated, history = carry
        repeated = repeated and token == initial
    if repeated:
        value = onset(token)
    elif token.strip() == 'EOF' and '<<' in history:
        value = 0.50
    elif token == ':' and history == 'Title':
        value = 0.51
    elif '\n' in token:
        value = -0.02
    else:
        value = 0.002
    return (doc, initial, repeated, (history + token)[-40:]), value

programs.haiku:
"""Document-opening tokens: the component is strongly negative on the first token of each
document (value depends a little on what kind of token it is) and near zero everywhere else."""

READS = ()


def step(carry, prefix, upstream):
    t = prefix.position
    if t > 0 and prefix.document_ids[t] == prefix.document_ids[t - 1]:
        return carry, 0.0
    s = prefix.token_strings[t]
    first = s[:1]
    if first.isspace() and s[1:2].isalpha():
        value = -0.45  # word with a leading space, e.g. " the"
    elif first.isascii() and first.isalpha():
        value = -0.65 if first.islower() else -0.58  # bare word or fragment
    elif first.isalpha():
        value = -0.33 if "一" <= first <= "鿿" else -0.6  # CJK vs other scripts
    else:
        value = -0.55  # punctuation, digits, symbols, line breaks
    return carry, value

programs.sol:
"""Recognize OIL-like spellings, strongest across token boundaries.

Whole-token forms such as oil, coil, soil and boil get different strengths.
Completing o + il is stronger than seeing the same spelling in one token.
The related OY+L, OEIL and umlaut spellings are also recognized. Other
O-vowel continuations get smaller signed responses. Oxygen formulas are
an additional cue, alongside Japanese oil and Chinese oil/coil spellings.
Unhandled tokens get zero; document boundaries reset our two-token memory. These rules omit most weak contextual variation.
"""
import re

READS = ()


def spelling(previous, token):
    word = token.strip().lower()
    before = previous.lower()
    value = 0.0
    match = re.fullmatch(
        r'(oil|coil|recoil|soil|foil|boil|toil)(s|ed|ing|y|er|ers)?', word
    )
    if match:
        root, ending = match.groups()
        value = 5.2
        if root in ('coil', 'recoil'):
            value = 7.0
        elif root == 'soil':
            value = 3.2
        elif root == 'boil':
            value = 4.6
        if ending in ('ing', 'ed', 'y'):
            value *= 0.72
        elif ending in ('er', 'ers'):
            value *= 0.3
        elif root == 'oil' and ending == 's':
            value = 6.2
        if token.strip()[0].isupper():
            value += 0.7
    elif 'oyl' in word:
        value = 2.8
    elif word in ('toilet', 'flour'):
        value = 0.7
    elif word == 'dioxide':
        value = 3.0
    elif token == '油':
        value = 1.8
    elif token == 'öl' and not before.endswith(('v', 'zw')):
        value = 4.5

    if not token or token[0].isspace():
        return value
    if before.endswith('o'):
        if re.fullmatch(r'il(ed|s)?', word):
            value = 7.5
            if before.endswith('co'):
                value += 3.0
            elif before.endswith(('so', 'bo')):
                value -= 1.5
            if word == 'iled':
                value += 3.5
        elif word.startswith('il'):
            value = 4.0
        elif word.startswith(('ie', 'ix', 'io')):
            value = -2.5
        elif word == 'ing':
            value = -1.0
        elif word == 'i':
            value = 0.0
        elif word.startswith('i'):
            value = 1.0
        elif word.startswith('yl'):
            value = 6.0
        elif word.startswith('eil'):
            value = 4.3
        elif word.startswith(('el', 'ethyl')):
            value = 0.8
        elif word.startswith(('e', 'ë', 'y')):
            value = -1.2
    elif before.endswith(('oi', 'oy')):
        if word.startswith('l'):
            value = 6.0
        elif word.startswith('e'):
            value = -2.7
    elif before.endswith(('ö', 'œ')):
        if word.startswith(('l', 'il')):
            value = 4.0
        elif word.startswith(('ss', 'ß', 'ch')):
            value = -2.5
    if previous.endswith('オ') and token.startswith('イル'):
        value = 12.0
    if previous.endswith('线') and token == '圈':
        value = 7.5
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, earlier = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    value = spelling(previous, token)
    # Formulas may have a separating space or a plain-text subscript marker.
    chemical = earlier if previous.strip() in ('', '~', '_') else previous
    if token == '2':
        formula = chemical.strip()
        if formula.endswith('CO'):
            value = 4.8 if chemical == previous else 3.0
        elif formula.endswith('NO'):
            value = 3.3 if chemical == previous else 1.5
        elif formula.endswith('O'):
            value = 1.8
    return (doc, token, previous), value

"""Approximate tool-completion pulses and Greek letter-sequence responses.

Closing a tool call gives a negative pulse, roughly twice the pulse for
closing its response. On nu after a separately tokenized Greek letter,
omicron/eta/iota give negative values and upsilon gives positive values,
especially in συν. Accents and word boundaries refine these estimates.
Small marker responses and runs of double middle dots are also included.
Unhandled tokens get zero; previous-document text is never used.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if start else prefix.token_strings[-2]

    if token == '</tool_call>':
        value = (-0.25 if start else
                 -0.82 if previous == '<tool_call>' else -2.02)
    elif token == '</tool_response>':
        value = -0.24 if start else -0.96
    elif token == '<tool_response>':
        value = 0.25
    elif token == '<think>':
        value = -0.19
    elif token == '··' and (start or previous == token):
        value = 1.18
    elif token == 'ν':
        # Only a few tokens are needed for the preceding Greek letters.
        pieces = []
        for i in range(max(0, prefix.position - 3), prefix.position):
            if prefix.document_ids[i] == prefix.document_ids[-1]:
                pieces.append(prefix.token_bytes[i])
        context = b''.join(pieces).decode('utf-8', 'replace')
        if '\ufffd' in previous:
            # Preserve a word boundary when completing split UTF-8 bytes.
            previous = (context[-2:] if context[-2:-1].isspace()
                        else context[-1:])
        letter = previous.strip()
        value = 0.0
        if len(letter) == 1:
            decomposed = unicodedata.normalize('NFD', letter.lower())
            base = decomposed[0]
            if base == 'ο':
                value = -6.8
            elif base in 'ηι':
                value = -3.5
            elif base == 'υ':
                value = (3.3 if len(decomposed) > 1 else
                         8.0 if context.lower().endswith('συ') else 5.0)
            elif base in 'αε' and (previous[:1].isspace() or letter.isupper()):
                value = 2.9
            elif letter == 'ῶ':
                value = 2.9
            elif letter == 'ω':
                value = 0.8
            elif letter == 'χ':
                value = 4.4
    else:
        value = 0.0
    return None, value
